export function createHealthBar() {
  const c = document.createElement('canvas');
  c.width = 192; c.height = 40;
  const ctx = c.getContext('2d');
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  const sprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, depthWrite: false, depthTest: false }));
  sprite.scale.set(2.15, 0.45, 1);
  const draw = (ratio, label = '', boss = false) => {
    ctx.clearRect(0, 0, 192, 40);
    if (label) {
      ctx.font = '700 15px Outfit, sans-serif';
      ctx.textAlign = 'center';
      ctx.fillStyle = 'rgba(8,18,20,0.62)';
      ctx.fillText(label, 96, 14);
      ctx.fillStyle = '#fff8e8';
      ctx.fillText(label, 96, 13);
    }
    const x = 16, y = label ? 20 : 10, w = 160, h = 9;
    ctx.fillStyle = 'rgba(6,15,18,0.80)';
    ctx.beginPath(); ctx.roundRect(x - 2, y - 2, w + 4, h + 4, 5); ctx.fill();
    ctx.fillStyle = boss ? '#ff5a24' : '#ff6b5a';
    ctx.beginPath(); ctx.roundRect(x, y, w * clamp(ratio, 0, 1), h, 3); ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,0.36)';
    ctx.beginPath(); ctx.roundRect(x, y, w * clamp(ratio, 0, 1), 3, 2); ctx.fill();
    tex.needsUpdate = true;
  };
  draw(1);
  return { sprite, draw, texture: tex };
}

export function createMarker(kind = '!') {
  const c = document.createElement('canvas');
  c.width = c.height = 128;
  const ctx = c.getContext('2d');
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  const sprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, depthWrite: false, depthTest: false }));
  sprite.scale.set(1.1, 1.1, 1);
  const draw = (icon = kind, color = '#ffc63c') => {
    ctx.clearRect(0, 0, 128, 128);
    ctx.beginPath(); ctx.arc(64, 64, 43, 0, TAU);
    ctx.fillStyle = 'rgba(10,24,26,0.72)'; ctx.fill();
    ctx.lineWidth = 6; ctx.strokeStyle = color; ctx.stroke();
    ctx.fillStyle = color;
    ctx.font = '700 70px Bangers, sans-serif';
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillText(icon, 64, 70);
    tex.needsUpdate = true;
  };
  draw(kind);
  return { sprite, draw, texture: tex };
}

import * as THREE from 'three';
import { clamp, TAU } from './noise.js';

/* ------------------------------------------------------------------ */
/*  GPU particle pool                                                  */
/* ------------------------------------------------------------------ */

const PARTICLE_VERT = /* glsl */`
  attribute float aSize;
  attribute float aAlpha;
  attribute vec3 aColor;
  varying float vAlpha;
  varying vec3 vColor;
  void main() {
    vAlpha = aAlpha;
    vColor = aColor;
    vec4 mv = modelViewMatrix * vec4(position, 1.0);
    gl_PointSize = aSize * (330.0 / max(-mv.z, 0.1));
    gl_Position = projectionMatrix * mv;
  }
`;

const PARTICLE_FRAG = /* glsl */`
  varying float vAlpha;
  varying vec3 vColor;
  void main() {
    vec2 p = gl_PointCoord - 0.5;
    float d = length(p);
    if (d > 0.5) discard;
    float glow = smoothstep(0.5, 0.06, d);
    gl_FragColor = vec4(vColor, vAlpha * glow);
  }
`;

export class Particles {
  constructor(scene, capacity = 900) {
    this.capacity = capacity;
    this.positions = new Float32Array(capacity * 3);
    this.colors = new Float32Array(capacity * 3);
    this.sizes = new Float32Array(capacity);
    this.alphas = new Float32Array(capacity);
    this.vel = new Float32Array(capacity * 3);
    this.life = new Float32Array(capacity);
    this.maxLife = new Float32Array(capacity);
    this.gravity = new Float32Array(capacity);
    this.drag = new Float32Array(capacity);
    this.baseSize = new Float32Array(capacity);
    this.cursor = 0;

    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(this.positions, 3).setUsage(THREE.DynamicDrawUsage));
    geo.setAttribute('aColor', new THREE.BufferAttribute(this.colors, 3).setUsage(THREE.DynamicDrawUsage));
    geo.setAttribute('aSize', new THREE.BufferAttribute(this.sizes, 1).setUsage(THREE.DynamicDrawUsage));
    geo.setAttribute('aAlpha', new THREE.BufferAttribute(this.alphas, 1).setUsage(THREE.DynamicDrawUsage));
    const material = new THREE.ShaderMaterial({
      vertexShader: PARTICLE_VERT,
      fragmentShader: PARTICLE_FRAG,
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
    });
    this.points = new THREE.Points(geo, material);
    this.points.frustumCulled = false;
    this.points.renderOrder = 5;
    scene.add(this.points);
    this.geo = geo;
    this.scene = scene;
  }

  spawn(x, y, z, {
    color = 0xffc86a, count = 1, speed = 2, size = 0.6, life = 0.8,
    gravity = 4, spread = 1, drag = 0.8, up = 1,
  } = {}) {
    const c = new THREE.Color(color);
    for (let i = 0; i < count; i++) {
      const idx = this.cursor;
      this.cursor = (this.cursor + 1) % this.capacity;
      const a = Math.random() * TAU;
      const b = Math.acos(Math.random() * 2 - 1);
      const sp = speed * (0.35 + Math.random() * 0.9);
      const pos = idx * 3;
      this.positions[pos] = x + (Math.random() - 0.5) * spread;
      this.positions[pos + 1] = y + (Math.random() - 0.5) * spread;
      this.positions[pos + 2] = z + (Math.random() - 0.5) * spread;
      this.vel[pos] = Math.sin(b) * Math.cos(a) * sp;
      this.vel[pos + 1] = Math.abs(Math.cos(b)) * sp * up + 0.4;
      this.vel[pos + 2] = Math.sin(b) * Math.sin(a) * sp;
      const tint = 0.8 + Math.random() * 0.4;
      this.colors[pos] = c.r * tint;
      this.colors[pos + 1] = c.g * tint;
      this.colors[pos + 2] = c.b * tint;
      this.baseSize[idx] = size * (0.55 + Math.random() * 0.9);
      this.sizes[idx] = this.baseSize[idx];
      this.alphas[idx] = 1;
      this.life[idx] = life * (0.65 + Math.random() * 0.7);
      this.maxLife[idx] = this.life[idx];
      this.gravity[idx] = gravity;
      this.drag[idx] = drag;
    }
    this.geo.attributes.position.needsUpdate = true;
    this.geo.attributes.aColor.needsUpdate = true;
    this.geo.attributes.aSize.needsUpdate = true;
    this.geo.attributes.aAlpha.needsUpdate = true;
  }

  update(dt) {
    for (let i = 0; i < this.capacity; i++) {
      if (this.life[i] <= 0) { this.alphas[i] = 0; continue; }
      this.life[i] -= dt;
      const p = i * 3;
      const d = Math.exp(-this.drag[i] * dt);
      this.vel[p] *= d;
      this.vel[p + 1] = this.vel[p + 1] * d - this.gravity[i] * dt;
      this.vel[p + 2] *= d;
      this.positions[p] += this.vel[p] * dt;
      this.positions[p + 1] += this.vel[p + 1] * dt;
      this.positions[p + 2] += this.vel[p + 2] * dt;
      const t = clamp(this.life[i] / this.maxLife[i], 0, 1);
      this.alphas[i] = Math.pow(t, 1.4);
      this.sizes[i] = this.baseSize[i] * (0.35 + t * 0.75);
      if (this.life[i] <= 0) this.alphas[i] = 0;
    }
    this.geo.attributes.position.needsUpdate = true;
    this.geo.attributes.aSize.needsUpdate = true;
    this.geo.attributes.aAlpha.needsUpdate = true;
  }
}

/* ------------------------------------------------------------------ */
/*  Floating combat text                                               */
/* ------------------------------------------------------------------ */

const TEMP = new THREE.Vector3();

export class FloatingText {
  constructor(container, camera) {
    this.container = container;
    this.camera = camera;
    this.items = [];
    this.width = window.innerWidth;
    this.height = window.innerHeight;
  }

  spawn(position, text, kind = 'damage', options = {}) {
    const el = document.createElement('div');
    el.className = `floaters ${kind}`;
    el.textContent = text;
    if (options.crit) el.classList.add('crit');
    this.container.appendChild(el);
    this.items.push({
      el,
      pos: position.clone().add(new THREE.Vector3((Math.random() - 0.5) * 0.7, 2.5 + Math.random() * 0.6, (Math.random() - 0.5) * 0.7)),
      life: options.life || 1.05,
      max: options.life || 1.05,
      drift: (Math.random() - 0.5) * 34,
      scale: options.scale || 1,
    });
  }

  update(dt) {
    this.width = window.innerWidth;
    this.height = window.innerHeight;
    for (let i = this.items.length - 1; i >= 0; i--) {
      const item = this.items[i];
      item.life -= dt;
      if (item.life <= 0) {
        item.el.remove();
        this.items.splice(i, 1);
        continue;
      }
      item.pos.y += dt * 1.6;
      TEMP.copy(item.pos).project(this.camera);
      const visible = TEMP.z < 1;
      const x = (TEMP.x * 0.5 + 0.5) * this.width + item.drift * (1 - item.life / item.max);
      const y = (-TEMP.y * 0.5 + 0.5) * this.height;
      const t = item.life / item.max;
      item.el.style.opacity = visible ? String(Math.min(1, t * 2.4)) : '0';
      const pop = 1 + Math.sin(Math.min(1, (1 - t) * 4) * Math.PI) * 0.28;
      item.el.style.transform = `translate(-50%,-50%) translate(${x.toFixed(1)}px, ${y.toFixed(1)}px) scale(${(pop * item.scale).toFixed(3)})`;
    }
  }

  clear() {
    this.items.forEach(i => i.el.remove());
    this.items.length = 0;
  }
}

/* ------------------------------------------------------------------ */
/*  World effects                                                      */
/* ------------------------------------------------------------------ */

export class Effects {
  constructor(scene, camera, particles, floating) {
    this.scene = scene;
    this.camera = camera;
    this.particles = particles;
    this.floating = floating;
    this.items = [];
    this.shake = 0;
    this.shakeTime = 0;
    this.flash = 0;
  }

  shakeCamera(amount) {
    this.shake = Math.max(this.shake, amount);
    this.shakeTime = 0;
  }

  screenFlash(amount) {
    this.flash = Math.max(this.flash, amount);
  }

  burst(pos, color = 0xffc86a, count = 18, options = {}) {
    this.particles.spawn(pos.x, pos.y, pos.z, { color, count, ...options });
  }

  ring(pos, color = 0xffa64a, radius = 2, duration = 0.55, thickness = 0.6) {
    const geo = new THREE.RingGeometry(Math.max(0.01, radius - thickness * radius), radius, 44, 1);
    const mat = new THREE.MeshBasicMaterial({
      color, transparent: true, opacity: 0.95, side: THREE.DoubleSide,
      blending: THREE.AdditiveBlending, depthWrite: false,
    });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.rotation.x = -Math.PI / 2;
    mesh.position.copy(pos);
    mesh.position.y += 0.08;
    mesh.renderOrder = 4;
    this.scene.add(mesh);
    this.items.push({ mesh, mat, life: duration, max: duration, kind: 'ring', radius });
  }

  slash(pos, yaw, color = 0x9ff6ff, scale = 1, flip = 1) {
    const geo = new THREE.RingGeometry(1.1 * scale, 3.0 * scale, 32, 1, 0, Math.PI * 0.95);
    const mat = new THREE.MeshBasicMaterial({
      color, transparent: true, opacity: 0.9, side: THREE.DoubleSide,
      blending: THREE.AdditiveBlending, depthWrite: false,
    });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.rotation.x = -Math.PI / 2;
    mesh.rotation.z = yaw + (flip > 0 ? -1.9 : -1.2);
    mesh.position.copy(pos);
    mesh.position.y += 1.25;
    mesh.renderOrder = 4;
    this.scene.add(mesh);
    this.items.push({ mesh, mat, life: 0.24, max: 0.24, kind: 'slash' });
  }

  explosion(pos, {
    color = 0xff8a2a, radius = 4, duration = 0.7, ringColor = 0xffc46a, particleCount = 34,
  } = {}) {
    const geo = new THREE.SphereGeometry(1, 14, 10);
    const mat = new THREE.MeshBasicMaterial({
      color, transparent: true, opacity: 0.95, blending: THREE.AdditiveBlending, depthWrite: false,
    });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.position.copy(pos);
    mesh.scale.setScalar(0.4);
    this.scene.add(mesh);
    this.items.push({ mesh, mat, life: duration, max: duration, kind: 'explosion', radius });
    const core = new THREE.Mesh(new THREE.SphereGeometry(1, 8, 6), new THREE.MeshBasicMaterial({
      color: 0xfff3c9, transparent: true, opacity: 1, blending: THREE.AdditiveBlending, depthWrite: false,
    }));
    core.position.copy(pos);
    core.scale.setScalar(0.2);
    this.scene.add(core);
    this.items.push({ mesh: core, mat: core.material, life: duration * 0.55, max: duration * 0.55, kind: 'core' });
    this.ring(pos, ringColor, radius * 1.25, duration * 0.85, 1.2);
    this.particles.spawn(pos.x, pos.y, pos.z, {
      color, count: particleCount, speed: radius * 2.2, size: 1.2, life: 0.9, gravity: 1.5, spread: 0.7, drag: 1.4,
    });
    this.particles.spawn(pos.x, pos.y, pos.z, {
      color: 0xfff0b0, count: Math.floor(particleCount * 0.4), speed: radius * 1.1, size: 0.8, life: 0.5, gravity: 0.5, spread: 0.4, drag: 2,
    });
    this.shakeCamera(0.34);
    this.screenFlash(0.22);
  }

  pillars(pos, color = 0xff5a1a, count = 8, radius = 6) {
    for (let i = 0; i < count; i++) {
      const a = (i / count) * TAU;
      const x = pos.x + Math.cos(a) * radius;
      const z = pos.z + Math.sin(a) * radius;
      const geo = new THREE.CylinderGeometry(0.4, 0.1, 1, 6, 1, true);
      const mat = new THREE.MeshBasicMaterial({
        color, transparent: true, opacity: 0.85, side: THREE.DoubleSide,
        blending: THREE.AdditiveBlending, depthWrite: false,
      });
      const mesh = new THREE.Mesh(geo, mat);
      mesh.position.set(x, pos.y, z);
      mesh.scale.y = 0.1;
      this.scene.add(mesh);
      this.items.push({ mesh, mat, life: 0.65, max: 0.65, kind: 'pillar', burst: true });
      this.particles.spawn(x, pos.y + 0.4, z, { color, count: 8, speed: 5, size: 0.9, life: 0.6, gravity: -1.5, drag: 1.5 });
    }
  }

  heal(pos, color = 0x7dffb0) {
    this.particles.spawn(pos.x, pos.y, pos.z, { color, count: 24, speed: 2.4, size: 0.7, life: 1.2, gravity: -2.2, spread: 0.6, drag: 0.4 });
    this.ring(pos, color, 2.5, 0.8, 0.15);
  }

  telegraph(pos, radius, duration = 1.2, color = 0xff4018) {
    const geo = new THREE.RingGeometry(radius * 0.92, radius, 48, 1);
    const mat = new THREE.MeshBasicMaterial({
      color, transparent: true, opacity: 0.7, side: THREE.DoubleSide, depthWrite: false,
    });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.rotation.x = -Math.PI / 2;
    mesh.position.copy(pos);
    mesh.position.y += 0.12;
    this.scene.add(mesh);
    const fillMat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.16, side: THREE.DoubleSide, depthWrite: false });
    const fill = new THREE.Mesh(new THREE.CircleGeometry(radius, 48), fillMat);
    fill.rotation.x = -Math.PI / 2;
    fill.position.copy(mesh.position);
    fill.position.y += 0.01;
    this.scene.add(fill);
    const item = { mesh, mat, fill, fillMat, life: duration, max: duration, kind: 'telegraph' };
    this.items.push(item);
    return item;
  }

  update(dt, time) {
    this.shake = Math.max(0, this.shake - dt * 2.4);
    this.flash = Math.max(0, this.flash - dt * 3.6);
    for (let i = this.items.length - 1; i >= 0; i--) {
      const it = this.items[i];
      it.life -= dt;
      const t = clamp(it.life / it.max, 0, 1);
      const p = 1 - t;
      if (it.life <= 0) {
        if (it.fill) { this.scene.remove(it.fill); it.fill.geometry.dispose(); it.fillMat.dispose(); }
        this.scene.remove(it.mesh);
        it.mesh.geometry.dispose();
        it.mat.dispose();
        this.items.splice(i, 1);
        continue;
      }
      if (it.kind === 'explosion') {
        it.mesh.scale.setScalar(0.4 + p * it.radius * 1.35);
        it.mat.opacity = Math.pow(t, 0.7) * 0.85;
      } else if (it.kind === 'core') {
        it.mesh.scale.setScalar(0.2 + p * 2.1);
        it.mat.opacity = t;
      } else if (it.kind === 'ring') {
        it.mesh.scale.setScalar(0.25 + p * 1.3);
        it.mat.opacity = Math.pow(t, 1.2) * 0.95;
      } else if (it.kind === 'slash') {
        it.mesh.scale.setScalar(1 + p * 0.6);
        it.mat.opacity = Math.sin(t * Math.PI) * 0.9;
      } else if (it.kind === 'pillar') {
        it.mesh.scale.y = 0.1 + p * 7;
        it.mesh.position.y += dt * 1.2;
        it.mat.opacity = t * 0.8;
      } else if (it.kind === 'telegraph') {
        it.mat.opacity = 0.35 + Math.sin(time * 18) * 0.2 + p * 0.35;
        it.fillMat.opacity = 0.05 + p * 0.2;
        it.mesh.scale.setScalar(1 + Math.sin(time * 8) * 0.015);
      }
    }
    this.particles.update(dt);
    this.floating.update(dt);
  }

  ambient(time, dt, playerPos, biome) {
    // Cheap atmosphere: leaves around the home island, embers on the volcano.
    if (Math.random() > dt * 13) return;
    if (biome === 'ember') {
      this.particles.spawn(playerPos.x + (Math.random() - 0.5) * 45, playerPos.y + 4 + Math.random() * 10, playerPos.z + (Math.random() - 0.5) * 45, {
        color: Math.random() > 0.5 ? 0xff5a1a : 0xffb020, count: 1, speed: 0.5, size: 0.28, life: 3, gravity: -0.25, spread: 2, drag: 0.1,
      });
    } else if (biome === 'home') {
      this.particles.spawn(playerPos.x + (Math.random() - 0.5) * 36, playerPos.y + 2 + Math.random() * 5, playerPos.z + (Math.random() - 0.5) * 36, {
        color: Math.random() > 0.5 ? 0xb9e26a : 0x7fcf5a, count: 1, speed: 0.4, size: 0.22, life: 4, gravity: -0.05, spread: 2, drag: 0.02,
      });
    }
  }
}

// Fully synthesised audio: ocean ambience, a sparse adventure score, and SFX.
// Nothing is loaded from the network, and the context starts on the first click.
export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.musicGain = null;
    this.sfxGain = null;
    this.muted = localStorage.getItem('fruitbound-muted') === '1';
    this.timer = null;
    this.step = 0;
    this.noiseBuffer = null;
    this.enabled = false;
  }

  init() {
    if (this.ctx) { if (this.ctx.state === 'suspended') this.ctx.resume(); return; }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    const ctx = this.ctx = new AC();
    this.master = ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.6;
    const comp = ctx.createDynamicsCompressor();
    comp.threshold.value = -16; comp.knee.value = 14; comp.ratio.value = 5;
    this.master.connect(comp); comp.connect(ctx.destination);
    this.musicGain = ctx.createGain(); this.musicGain.gain.value = 0.18; this.musicGain.connect(this.master);
    this.sfxGain = ctx.createGain(); this.sfxGain.gain.value = 0.55; this.sfxGain.connect(this.master);

    const len = ctx.sampleRate * 2.5;
    const buffer = ctx.createBuffer(1, len, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    let last = 0;
    for (let i = 0; i < len; i++) {
      const white = Math.random() * 2 - 1;
      last = (last + 0.02 * white) / 1.02;
      data[i] = last * 3.2;
    }
    this.noiseBuffer = buffer;

    this.startAmbience();
    this.startMusic();
    this.enabled = true;
  }

  setMuted(m) {
    this.muted = m;
    localStorage.setItem('fruitbound-muted', m ? '1' : '0');
    if (this.master) this.master.gain.setTargetAtTime(m ? 0 : 0.6, this.ctx.currentTime, 0.12);
  }

  toggleMute() { this.setMuted(!this.muted); return this.muted; }

  startAmbience() {
    const ctx = this.ctx;
    const source = ctx.createBufferSource();
    source.buffer = this.noiseBuffer; source.loop = true;
    const lp = ctx.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.value = 520; lp.Q.value = 0.4;
    const gain = ctx.createGain(); gain.gain.value = 0.055;
    const lfo = ctx.createOscillator(); lfo.frequency.value = 0.08;
    const lfoGain = ctx.createGain(); lfoGain.gain.value = 0.032;
    lfo.connect(lfoGain); lfoGain.connect(gain.gain);
    source.connect(lp); lp.connect(gain); gain.connect(this.master);
    source.start(); lfo.start();

    // High, airy wind.
    const wind = ctx.createBufferSource(); wind.buffer = this.noiseBuffer; wind.loop = true;
    const hp = ctx.createBiquadFilter(); hp.type = 'highpass'; hp.frequency.value = 1600;
    const wg = ctx.createGain(); wg.gain.value = 0.012;
    const wlfo = ctx.createOscillator(); wlfo.frequency.value = 0.05;
    const wlg = ctx.createGain(); wlg.gain.value = 0.009;
    wlfo.connect(wlg); wlg.connect(wg.gain);
    wind.connect(hp); hp.connect(wg); wg.connect(this.master);
    wind.start(); wlfo.start();
  }

  startMusic() {
    if (this.timer) return;
    const chord = [146.83, 174.61, 220.0, 261.63];
    const melody = [293.66, 349.23, 440.0, 392.0, 349.23, 293.66, 261.63, 220.0];
    this.pad(chord, 9);
    this.timer = setInterval(() => {
      if (!this.ctx || this.muted) return;
      const t = this.ctx.currentTime;
      const note = melody[this.step % melody.length];
      this.pluck(note, t, 0.05, 0.5);
      if (this.step % 4 === 0) this.pluck(note / 2, t, 0.045, 1.4);
      if (this.step % 8 === 4) this.pad(chord.map(f => f * (Math.random() > 0.5 ? 1 : 1.5)), 8);
      this.step++;
    }, 620);
  }

  pad(freqs, seconds) {
    const ctx = this.ctx; if (!ctx) return;
    const t = ctx.currentTime;
    for (const f of freqs) {
      const o = ctx.createOscillator(); o.type = 'sine'; o.frequency.value = f;
      const o2 = ctx.createOscillator(); o2.type = 'triangle'; o2.frequency.value = f * 1.004;
      const g = ctx.createGain();
      g.gain.setValueAtTime(0, t);
      g.gain.linearRampToValueAtTime(0.035, t + 1.2);
      g.gain.linearRampToValueAtTime(0.0, t + seconds);
      o.connect(g); o2.connect(g); g.connect(this.musicGain);
      o.start(t); o2.start(t); o.stop(t + seconds + 0.1); o2.stop(t + seconds + 0.1);
    }
  }

  pluck(freq, t, gain = 0.05, decay = 0.8) {
    const ctx = this.ctx; if (!ctx) return;
    const o = ctx.createOscillator(); o.type = 'triangle'; o.frequency.value = freq;
    const o2 = ctx.createOscillator(); o2.type = 'sine'; o2.frequency.value = freq * 2;
    const g = ctx.createGain();
    g.gain.setValueAtTime(gain, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + decay);
    const f = ctx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = 2200;
    o.connect(f); o2.connect(f); f.connect(g); g.connect(this.musicGain);
    o.start(t); o2.start(t); o.stop(t + decay); o2.stop(t + decay);
  }

  noise(duration, { gain = 0.2, type = 'bandpass', freq = 1200, q = 1, freqEnd = null } = {}) {
    const ctx = this.ctx; if (!ctx) return;
    const src = ctx.createBufferSource(); src.buffer = this.noiseBuffer;
    const f = ctx.createBiquadFilter(); f.type = type; f.frequency.setValueAtTime(freq, ctx.currentTime); f.Q.value = q;
    if (freqEnd) f.frequency.exponentialRampToValueAtTime(freqEnd, ctx.currentTime + duration);
    const g = ctx.createGain();
    g.gain.setValueAtTime(gain, ctx.currentTime);
    g.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + duration);
    src.connect(f); f.connect(g); g.connect(this.sfxGain);
    src.start(); src.stop(ctx.currentTime + duration + 0.02);
  }

  tone(freq, duration, { type = 'sine', gain = 0.16, slide = 0, delay = 0 } = {}) {
    const ctx = this.ctx; if (!ctx) return;
    const t = ctx.currentTime + delay;
    const o = ctx.createOscillator(); o.type = type;
    o.frequency.setValueAtTime(freq, t);
    if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(20, slide), t + duration);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(gain, t + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t + duration);
    o.connect(g); g.connect(this.sfxGain);
    o.start(t); o.stop(t + duration + 0.02);
  }

  swing() { this.noise(0.18, { gain: 0.18, freq: 900, freqEnd: 2600, q: 1.2 }); }
  hit(crit = false) {
    this.noise(0.12, { gain: crit ? 0.32 : 0.2, freq: 420, freqEnd: 130, q: 0.8 });
    this.tone(crit ? 150 : 190, 0.13, { type: 'square', gain: 0.09, slide: 70 });
  }
  dash() { this.noise(0.30, { gain: 0.16, freq: 350, freqEnd: 1400, q: 0.9 }); }
  fireball() {
    this.noise(0.42, { gain: 0.2, freq: 600, freqEnd: 170, q: 0.6 });
    this.tone(220, 0.3, { type: 'sawtooth', gain: 0.06, slide: 80 });
  }
  explosion() {
    this.noise(0.7, { gain: 0.42, type: 'lowpass', freq: 900, freqEnd: 80, q: 0.5 });
    this.tone(70, 0.6, { type: 'sine', gain: 0.3, slide: 32 });
    this.noise(0.2, { gain: 0.2, type: 'highpass', freq: 1600 });
  }
  coin() {
    this.tone(980, 0.08, { type: 'triangle', gain: 0.09 });
    this.tone(1460, 0.14, { type: 'triangle', gain: 0.06, delay: 0.05 });
  }
  heal() {
    [523, 659, 784, 1046].forEach((f, i) => this.tone(f, 0.5, { type: 'sine', gain: 0.07, delay: i * 0.08 }));
  }
  levelUp() {
    [392, 523, 659, 784, 1046].forEach((f, i) => this.tone(f, 0.7, { type: 'triangle', gain: 0.10, delay: i * 0.09 }));
  }
  quest() {
    [523, 659, 784, 1046, 1318].forEach((f, i) => this.tone(f, 0.8, { type: 'sine', gain: 0.09, delay: i * 0.1 }));
  }
  click() { this.tone(660, 0.06, { type: 'sine', gain: 0.06 }); }
  error() { this.tone(180, 0.16, { type: 'square', gain: 0.05, slide: 120 }); }
  chest() {
    this.noise(0.4, { gain: 0.1, freq: 700, freqEnd: 2400 });
    [523, 784, 1046, 1318].forEach((f, i) => this.tone(f, 0.45, { type: 'triangle', gain: 0.07, delay: 0.15 + i * 0.06 }));
  }
  roar() {
    this.noise(1.1, { gain: 0.35, type: 'lowpass', freq: 240, freqEnd: 70, q: 2 });
    this.tone(58, 1.0, { type: 'sawtooth', gain: 0.12, slide: 38 });
  }
  wave() { this.noise(0.8, { gain: 0.16, freq: 240, freqEnd: 900, q: 0.5 }); }
  board() { this.noise(0.5, { gain: 0.09, freq: 500, freqEnd: 200 }); }
  hurt() { this.tone(120, 0.25, { type: 'sawtooth', gain: 0.08, slide: 60 }); }
}

@font-face {
  font-family: 'Bangers';
  src: url('./assets/fonts/bangers.woff2') format('woff2');
  font-weight: 400;
  font-display: swap;
}
@font-face {
  font-family: 'Outfit';
  src: url('./assets/fonts/outfit.woff2') format('woff2');
  font-weight: 100 900;
  font-display: swap;
}

:root {
  --ink: #071c24;
  --ink-2: #0c2a33;
  --glass: rgba(7, 27, 34, 0.66);
  --glass-2: rgba(9, 33, 41, 0.84);
  --line: rgba(150, 232, 224, 0.20);
  --cream: #f7f0dc;
  --muted: #9ec6c2;
  --teal: #2ed9c3;
  --teal-deep: #0f9d96;
  --gold: #ffc857;
  --gold-deep: #d68c2a;
  --coral: #ff6a4d;
  --hp: #ff5f57;
  --energy: #35d7ff;
  --xp: #ffc857;
  --shadow: 0 18px 50px rgba(0, 12, 16, 0.45);
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-right: env(safe-area-inset-right, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-left: env(safe-area-inset-left, 0px);
}

* { box-sizing: border-box; }
html, body {
  margin: 0; padding: 0; width: 100%; height: 100%;
  overflow: hidden; background: #041216;
  color: var(--cream);
  font-family: 'Outfit', system-ui, -apple-system, 'Segoe UI', sans-serif;
  -webkit-font-smoothing: antialiased;
  overscroll-behavior: none;
  -webkit-tap-highlight-color: transparent;
}
body { user-select: none; }
button { font-family: inherit; color: inherit; cursor: pointer; }
kbd {
  font-family: 'Outfit', sans-serif; font-size: 10px; font-weight: 800; letter-spacing: .06em;
  border: 1px solid rgba(190, 242, 235, .25); border-bottom-color: rgba(190, 242, 235, .12);
  background: rgba(219, 255, 249, .08); color: #dff8f2; border-radius: 5px;
  padding: 2px 6px; line-height: 1.2; display: inline-flex; align-items: center; justify-content: center;
}
.hidden { display: none !important; }

#app { position: fixed; inset: 0; }
#scene { position: absolute; inset: 0; width: 100%; height: 100%; display: block; touch-action: none; cursor: crosshair; }
#vignette {
  position: absolute; inset: 0; pointer-events: none; z-index: 1;
  background:
    radial-gradient(ellipse at center, transparent 52%, rgba(2, 14, 18, .34) 100%),
    linear-gradient(to bottom, rgba(3, 18, 23, .30), transparent 16%, transparent 82%, rgba(3, 16, 20, .40));
}
#grain {
  position: absolute; inset: 0; pointer-events: none; z-index: 2; opacity: .055;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.85' numOctaves='2' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.55'/%3E%3C/svg%3E");
  mix-blend-mode: overlay;
}
#vignette-hit {
  position: absolute; inset: 0; pointer-events: none; z-index: 60; opacity: 0;
  box-shadow: inset 0 0 160px 30px rgba(255, 24, 24, .65);
  transition: opacity .18s ease-out;
}
#flash { position: absolute; inset: 0; pointer-events: none; background: #fff; opacity: 0; z-index: 55; }

/* ------------------------------------------------------------------ */
/* HUD                                                                 */
/* ------------------------------------------------------------------ */
#hud { position: absolute; inset: 0; z-index: 10; pointer-events: none; }
#hud button, #hud .map-btn { pointer-events: auto; }

#top-left {
  position: absolute; top: calc(20px + var(--safe-top)); left: calc(22px + var(--safe-left));
  display: flex; flex-direction: column; gap: 9px;
}
.player-card {
  display: flex; align-items: center; gap: 12px;
  background: linear-gradient(135deg, rgba(8, 31, 38, .90), rgba(8, 27, 33, .62));
  border: 1px solid var(--line); border-left: 2px solid var(--gold);
  padding: 9px 18px 9px 9px;
  clip-path: polygon(0 0, 100% 0, calc(100% - 14px) 100%, 0 100%);
  backdrop-filter: blur(14px);
  box-shadow: var(--shadow);
  min-width: 252px;
}
.level-badge {
  width: 49px; height: 49px; border-radius: 50%;
  background: radial-gradient(circle at 34% 28%, #ffe6a3, var(--gold) 45%, #bd7520 100%);
  color: #2d1b02; display: flex; flex-direction: column; align-items: center; justify-content: center;
  line-height: 1; box-shadow: 0 0 0 3px rgba(255, 200, 87, .14), 0 8px 20px rgba(0,0,0,.35);
  flex: none;
}
.level-badge span { font-size: 8px; font-weight: 800; letter-spacing: .14em; opacity: .72; }
.level-badge b { font-family: 'Bangers', cursive; font-size: 25px; letter-spacing: .04em; margin-top: 1px; }
.player-meta { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.player-name { font-family: 'Bangers', cursive; font-size: 25px; letter-spacing: .08em; line-height: 1; color: #fff8e7; }
.player-name em {
  font-family: 'Outfit', sans-serif; font-style: normal; font-size: 8px; font-weight: 800;
  letter-spacing: .16em; color: var(--gold); border: 1px solid rgba(255, 200, 87, .3);
  padding: 2px 5px; border-radius: 3px; vertical-align: 3px; margin-left: 3px;
}
.bounty-row { display: flex; align-items: center; gap: 5px; font-size: 12px; font-weight: 700; color: #f3deb0; }
.bounty-row svg { width: 12px; height: 12px; fill: var(--gold); filter: drop-shadow(0 0 5px rgba(255,200,87,.5)); }
.bounty-row i { font-style: normal; font-size: 8px; font-weight: 800; letter-spacing: .16em; color: rgba(240, 230, 200, .46); margin-left: 1px; }

.wallet {
  display: inline-flex; align-items: center; gap: 7px; width: fit-content;
  background: rgba(7, 26, 32, .74); border: 1px solid var(--line);
  padding: 5px 9px 5px 7px; border-radius: 4px; backdrop-filter: blur(10px);
  font-weight: 700; font-size: 13px; color: #ffe8b1;
}
.coin-icon {
  width: 19px; height: 19px; border-radius: 50%;
  background: radial-gradient(circle at 32% 28%, #fff0b3, #ffc857 48%, #b56b1d);
  color: #5a3606; display: grid; place-items: center; font-size: 10px; font-weight: 900;
  box-shadow: 0 0 9px rgba(255,200,87,.38);
}
.wallet small { font-size: 8px; letter-spacing: .14em; opacity: .5; color: #fff; }
.icon-btn {
  width: 26px; height: 26px; border: 1px solid var(--line); background: rgba(255,255,255,.05);
  border-radius: 4px; display: grid; place-items: center; padding: 0; margin-left: 3px;
  transition: background .18s, border-color .18s;
}
.icon-btn:hover { background: rgba(46, 217, 195, .16); border-color: rgba(46,217,195,.4); }
.icon-btn svg { width: 14px; height: 14px; fill: #c4e9e4; }

/* Compass */
#compass-wrap {
  position: absolute; top: calc(18px + var(--safe-top)); left: 50%; transform: translateX(-50%);
  width: min(360px, 32vw); display: flex; flex-direction: column; align-items: center; gap: 3px;
  transition: opacity .4s;
}
#compass-tape {
  position: relative; width: 100%; height: 31px; overflow: hidden;
  mask-image: linear-gradient(90deg, transparent, #000 16%, #000 84%, transparent);
  -webkit-mask-image: linear-gradient(90deg, transparent, #000 16%, #000 84%, transparent);
}
.compass-glow { position: absolute; left: 50%; top: 4px; width: 80px; height: 26px; transform: translateX(-50%); background: radial-gradient(ellipse, rgba(255,200,87,.18), transparent 70%); }
.compass-labels { position: absolute; inset: 0; }
.compass-labels span {
  position: absolute; left: 50%; top: 5px; transform: translateX(-50%);
  font-size: 10px; font-weight: 800; letter-spacing: .12em; color: rgba(230, 252, 247, .62);
  transition: color .12s;
}
.compass-labels span:nth-child(odd) { font-size: 8px; color: rgba(230,252,247,.34); top: 7px; }
.compass-needle {
  position: absolute; left: 50%; bottom: 0; width: 2px; height: 7px; transform: translateX(-50%);
  background: var(--gold); box-shadow: 0 0 8px var(--gold); border-radius: 2px;
}
#zone-name {
  font-size: 9px; font-weight: 800; letter-spacing: .30em; color: rgba(240, 255, 250, .66);
  text-shadow: 0 2px 8px rgba(0,0,0,.6); margin-top: 1px;
}

/* Minimap */
#minimap-wrap { position: absolute; top: calc(19px + var(--safe-top)); right: calc(21px + var(--safe-right)); }
.mini-frame { position: relative; width: 176px; height: 176px; }
#minimap {
  width: 100%; height: 100%; border-radius: 50%; display: block;
  background: rgba(3, 22, 28, .8);
  box-shadow: inset 0 0 30px rgba(0, 20, 25, .7), 0 12px 30px rgba(0,0,0,.4);
}
.mini-ring {
  position: absolute; inset: -5px; border-radius: 50%; pointer-events: none;
  border: 1px solid rgba(151, 235, 224, .32);
  box-shadow: 0 0 0 4px rgba(6, 25, 31, .35), inset 0 0 20px rgba(46,217,195,.12);
}
.mini-ring::before, .mini-ring::after {
  content: ''; position: absolute; border-radius: 50%; border: 1px solid transparent;
  border-top-color: rgba(255,200,87,.8); border-bottom-color: rgba(255,200,87,.5);
}
.mini-ring::before { inset: -8px; border-left-color: rgba(255,200,87,.1); border-right-color: rgba(255,200,87,.1); }
.mini-ring::after { inset: 12px; border-top-color: rgba(255,255,255,.06); border-bottom-color: rgba(255,255,255,.06); }
.mini-compass {
  position: absolute; font-size: 9px; font-weight: 800; color: rgba(255, 220, 140, .78);
  text-shadow: 0 1px 4px #000; pointer-events: none; z-index: 3;
}
.mini-compass.n { top: -19px; left: 50%; transform: translateX(-50%); color: var(--gold); }
.mini-compass.e { right: -16px; top: 50%; transform: translateY(-50%); }
.mini-compass.s { bottom: -19px; left: 50%; transform: translateX(-50%); }
.mini-compass.w { left: -16px; top: 50%; transform: translateY(-50%); }
.map-btn {
  position: absolute; left: 50%; bottom: -24px; transform: translateX(-50%);
  background: rgba(5, 24, 30, .85); border: 1px solid var(--line); color: #c9eee8;
  font-size: 8px; font-weight: 800; letter-spacing: .18em; padding: 4px 9px;
  border-radius: 3px; white-space: nowrap;
}
.map-btn kbd { margin-left: 4px; font-size: 8px; padding: 1px 4px; }
.map-btn:hover { border-color: rgba(46,217,195,.5); color: #fff; }

/* Quest tracker */
#quest-tracker {
  position: absolute; top: calc(224px + var(--safe-top)); right: calc(21px + var(--safe-right));
  width: 284px; padding: 12px 15px 12px 17px;
  background: linear-gradient(135deg, rgba(8, 30, 37, .86), rgba(7, 25, 31, .56));
  border: 1px solid var(--line); border-right: 2px solid var(--gold);
  clip-path: polygon(0 0, 100% 0, 100% 100%, 12px 100%);
  backdrop-filter: blur(12px); box-shadow: var(--shadow);
}
.quest-head { display: flex; align-items: center; gap: 7px; font-size: 8px; font-weight: 800; letter-spacing: .20em; color: var(--gold); }
.quest-diamond { width: 6px; height: 6px; background: var(--gold); transform: rotate(45deg); box-shadow: 0 0 7px var(--gold); }
.quest-chapter { margin-left: auto; color: rgba(220, 244, 239, .38); letter-spacing: .12em; }
#quest-title { margin: 8px 0 4px; font-family: 'Bangers', cursive; font-weight: 400; font-size: 24px; letter-spacing: .06em; line-height: 1; color: #fff7e3; }
#quest-objective { margin: 0; font-size: 11.5px; line-height: 1.35; color: #c2ddd9; font-weight: 400; min-height: 30px; }
.quest-progress { height: 4px; background: rgba(255,255,255,.08); margin-top: 9px; border-radius: 3px; overflow: hidden; }
#quest-fill { height: 100%; width: 0; background: linear-gradient(90deg, var(--gold-deep), var(--gold)); box-shadow: 0 0 8px rgba(255,200,87,.5); transition: width .4s ease; }
.quest-foot { display: flex; justify-content: space-between; margin-top: 5px; font-size: 9px; font-weight: 700; color: rgba(220, 244, 239, .48); letter-spacing: .06em; }
#quest-distance { color: rgba(255,200,87,.72); }

/* Boss bar */
#boss-bar {
  position: absolute; top: calc(76px + var(--safe-top)); left: 50%; transform: translateX(-50%);
  width: min(620px, 46vw); text-align: center; animation: bossIn .5s ease both;
}
@keyframes bossIn { from { opacity: 0; transform: translate(-50%, -10px); } to { opacity: 1; transform: translate(-50%, 0); } }
.boss-name { font-family: 'Bangers', cursive; font-size: 25px; letter-spacing: .10em; color: #ffe5cf; text-shadow: 0 2px 14px rgba(255, 70, 20, .5); }
.boss-name span { font-family: 'Outfit', sans-serif; font-size: 8px; font-weight: 800; letter-spacing: .3em; color: var(--coral); vertical-align: 5px; margin-right: 4px; }
.boss-hp { position: relative; height: 15px; margin-top: 4px; background: rgba(11, 4, 4, .78); border: 1px solid rgba(255, 108, 67, .38); transform: skewX(-16deg); overflow: hidden; }
#boss-fill { height: 100%; width: 100%; background: linear-gradient(90deg, #8f140c, #ff4f1b 55%, #ffb04a); box-shadow: 0 0 20px rgba(255, 80, 20, .5); transition: width .17s linear; }
.boss-hp i { position: absolute; inset: 2px; border-top: 1px solid rgba(255,255,255,.22); pointer-events: none; }
.boss-sub { display: flex; justify-content: space-between; margin-top: 4px; font-size: 8px; font-weight: 800; letter-spacing: .22em; color: rgba(255, 220, 195, .45); }
#boss-hp-text { color: #ffb797; }

/* Toast stack */
#toast-stack {
  position: absolute; top: calc(106px + var(--safe-top)); left: 50%; transform: translateX(-50%);
  display: flex; flex-direction: column; align-items: center; gap: 6px; width: min(420px, 44vw);
}
.toast {
  display: flex; align-items: center; gap: 9px; min-width: 180px; max-width: 100%;
  background: linear-gradient(135deg, rgba(6, 28, 34, .95), rgba(8, 33, 40, .78));
  border: 1px solid var(--line); border-left: 2px solid var(--teal);
  padding: 8px 14px 8px 11px; font-size: 11px; font-weight: 600; color: #dcf6f1;
  box-shadow: 0 10px 24px rgba(0,0,0,.35); backdrop-filter: blur(12px);
  clip-path: polygon(0 0, 100% 0, calc(100% - 8px) 100%, 0 100%);
  animation: toastIn .28s ease both;
}
.toast.out { animation: toastOut .3s ease both; }
.toast .t-icon { font-size: 14px; color: var(--gold); width: 18px; text-align: center; }
.toast.gold { border-left-color: var(--gold); }
.toast.danger { border-left-color: var(--coral); }
.toast b { color: var(--gold); }
@keyframes toastIn { from { opacity: 0; transform: translateY(-7px) scale(.97); } to { opacity: 1; transform: none; } }
@keyframes toastOut { to { opacity: 0; transform: translateY(-5px) scale(.97); } }

/* Crosshair */
#crosshair { position: absolute; left: 50%; top: 50%; width: 22px; height: 22px; transform: translate(-50%,-50%); opacity: .55; pointer-events: none; }
#crosshair i { position: absolute; background: rgba(240, 255, 250, .85); box-shadow: 0 0 4px rgba(0,0,0,.8); }
#crosshair i:nth-child(1) { width: 1px; height: 6px; left: 10.5px; top: 0; }
#crosshair i:nth-child(2) { width: 1px; height: 6px; left: 10.5px; bottom: 0; }
#crosshair i:nth-child(3) { width: 6px; height: 1px; top: 10.5px; left: 0; }
#crosshair i:nth-child(4) { width: 6px; height: 1px; top: 10.5px; right: 0; }
body.locked #crosshair { opacity: .85; }

/* Bottom-left status */
#bottom-left {
  position: absolute; left: calc(22px + var(--safe-left)); bottom: calc(24px + var(--safe-bottom));
  display: flex; flex-direction: column; gap: 8px;
}
.status-card {
  display: flex; align-items: center; gap: 10px;
  background: linear-gradient(135deg, rgba(8, 31, 38, .90), rgba(7, 25, 31, .58));
  border: 1px solid var(--line); border-left: 2px solid var(--hp);
  padding: 9px 15px 9px 9px; backdrop-filter: blur(13px); box-shadow: var(--shadow);
  clip-path: polygon(0 0, 100% 0, 100% 100%, 10px 100%);
}
.fruit-orb {
  position: relative; width: 52px; height: 52px; border-radius: 50%; flex: none;
  background: radial-gradient(circle at 34% 26%, #ffd27e, #ff7b2a 38%, #b3260f 76%, #5c1309);
  box-shadow: 0 0 15px rgba(255, 108, 34, .45), inset 0 -6px 12px rgba(60, 5, 0, .45);
  display: grid; place-items: center; overflow: hidden;
}
.fruit-orb b { font-family: 'Bangers', cursive; font-size: 25px; color: #fff4d7; text-shadow: 0 1px 3px rgba(80, 10, 0, .6); z-index: 2; }
.fruit-orb .fruit-swirl {
  position: absolute; inset: 5px; border-radius: 50%;
  background: repeating-conic-gradient(from 20deg, transparent 0 13deg, rgba(255, 231, 170, .22) 14deg 18deg);
  animation: spin 16s linear infinite;
}
.fruit-orb .fruit-leaf {
  position: absolute; width: 17px; height: 8px; top: -2px; right: 8px; border-radius: 100% 0 100% 0;
  background: #64b748; transform: rotate(-24deg); z-index: 3; box-shadow: 0 0 5px rgba(100, 183, 72, .4);
}
@keyframes spin { to { transform: rotate(360deg); } }
.status-bars { width: min(250px, 23vw); display: flex; flex-direction: column; gap: 4px; }
.bar-row { display: flex; align-items: center; gap: 6px; }
.bar {
  position: relative; height: 15px; flex: 1; background: rgba(0, 9, 12, .72);
  border: 1px solid rgba(255,255,255,.10); border-radius: 2px; overflow: hidden;
  transform: skewX(-10deg);
}
.bar-fill { height: 100%; width: 100%; transition: width .18s ease-out; }
.bar.hp .bar-fill { background: linear-gradient(90deg, #991515, #f2443b 58%, #ff8b68); }
.bar.energy .bar-fill { background: linear-gradient(90deg, #076b85, #1bb9e0 58%, #7ff2ff); }
.bar-shine { position: absolute; inset: 1px 1px auto 1px; height: 2px; background: rgba(255,255,255,.23); }
.bar span { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; font-size: 8px; font-weight: 800; letter-spacing: .05em; color: rgba(255,255,255,.86); text-shadow: 0 1px 2px rgba(0,0,0,.8); transform: skewX(10deg); }
.bar-label { font-size: 8px; font-weight: 800; color: rgba(220,244,239,.4); width: 15px; }
.xp-row { display: flex; align-items: center; gap: 7px; margin-top: 1px; }
.xp-bar { height: 3px; flex: 1; background: rgba(255,255,255,.09); border-radius: 2px; overflow: hidden; }
#xp-fill { height: 100%; width: 0; background: linear-gradient(90deg, #b98019, var(--gold)); box-shadow: 0 0 6px rgba(255,200,87,.6); transition: width .3s; }
#xp-text { font-size: 8px; font-weight: 700; color: rgba(240, 225, 190, .56); letter-spacing: .04em; }

#fruit-switcher { display: flex; gap: 5px; align-items: center; }
.fruit-chip {
  display: flex; align-items: center; gap: 4px; position: relative;
  background: rgba(5, 23, 29, .78); border: 1px solid rgba(150, 232, 224, .14);
  color: rgba(220, 244, 239, .44); font-size: 8px; font-weight: 800; letter-spacing: .10em;
  padding: 3px 6px 3px 4px; border-radius: 3px; backdrop-filter: blur(8px);
  pointer-events: auto;
}
.fruit-chip .chip-orb { width: 17px; height: 17px; border-radius: 50%; display: grid; place-items: center; font-size: 9px; color: #fff; }
.chip-orb.ember { background: radial-gradient(circle at 32% 30%, #ffca7a, #e04414 70%); }
.chip-orb.gale { background: radial-gradient(circle at 32% 30%, #c8fff4, #109b93 70%); }
.chip-orb.tide { background: radial-gradient(circle at 32% 30%, #9de6ff, #1456c7 70%); }
.fruit-chip.active { color: #fff2d0; border-color: rgba(255,200,87,.52); background: rgba(32, 39, 28, .86); box-shadow: 0 0 12px rgba(255,200,87,.12); }
.fruit-chip.locked { opacity: .48; }
.fruit-chip .lock { position: absolute; right: 2px; top: -5px; font-size: 7px; font-style: normal; }
.fruit-chip kbd { font-size: 7px; padding: 0 3px; }
.fruit-chip b { font-weight: 800; }

/* Hotbar */
#hotbar {
  position: absolute; bottom: calc(26px + var(--safe-bottom)); left: 50%; transform: translateX(-50%);
  display: flex; gap: 8px; pointer-events: auto;
}
.slot {
  position: relative; width: 76px; height: 76px; overflow: hidden;
  background: linear-gradient(150deg, rgba(9, 35, 42, .92), rgba(5, 20, 25, .80));
  border: 1px solid rgba(150, 232, 224, .18);
  clip-path: polygon(9px 0, 100% 0, 100% calc(100% - 9px), calc(100% - 9px) 100%, 0 100%, 0 9px);
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 1px;
  backdrop-filter: blur(12px); transition: transform .12s, border-color .15s;
}
.slot:hover { transform: translateY(-2px); border-color: rgba(255,200,87,.42); }
.slot.active { border-color: rgba(255, 200, 87, .72); box-shadow: inset 0 0 22px rgba(255, 200, 87, .12), 0 0 18px rgba(255, 200, 87, .16); }
.slot.fruit-slot { background: linear-gradient(150deg, rgba(43, 29, 15, .92), rgba(12, 24, 24, .82)); }
.slot .slot-key {
  position: absolute; left: 5px; top: 4px; font-size: 7px; font-weight: 800; letter-spacing: .08em;
  color: rgba(230, 255, 250, .44); border: 1px solid rgba(255,255,255,.13); border-radius: 2px;
  padding: 1px 3px; line-height: 1;
}
.slot .slot-icon { width: 27px; height: 27px; fill: #d5f1ec; filter: drop-shadow(0 2px 5px rgba(0,0,0,.5)); margin-top: 2px; }
.fruit-slot .slot-icon { fill: #ffce80; }
.slot .slot-name { font-size: 7.5px; font-weight: 800; letter-spacing: .09em; color: rgba(226, 249, 244, .7); }
.slot .slot-cost { position: absolute; right: 5px; top: 4px; font-size: 7px; font-weight: 800; color: #6fdcff; }
.slot .cooldown {
  position: absolute; inset: 0; background: rgba(2, 12, 15, .78); transform-origin: bottom;
  transform: scaleY(0); pointer-events: none; transition: transform .08s linear;
}
.slot .cd-text { position: absolute; inset: 0; display: grid; place-items: center; font-family: 'Bangers', cursive; font-size: 22px; color: #fff; text-shadow: 0 2px 8px #000; pointer-events: none; }
.slot.locked-ult { opacity: .5; }
.slot.locked-ult::after { content: 'LV 5'; position: absolute; inset: 0; display: grid; place-items: center; background: rgba(4,15,18,.7); font-size: 8px; font-weight: 800; letter-spacing: .12em; color: var(--gold); }
.slot.pulse { animation: slotPulse .3s ease; }
@keyframes slotPulse { 40% { transform: scale(1.08); border-color: var(--gold); } }

#interact-prompt {
  position: absolute; left: 50%; bottom: calc(119px + var(--safe-bottom)); transform: translateX(-50%);
  display: flex; align-items: center; gap: 9px; padding: 7px 15px 7px 7px;
  background: rgba(5, 24, 30, .88); border: 1px solid rgba(255,200,87,.38); border-radius: 4px;
  font-size: 11px; font-weight: 600; color: #f6efdc; box-shadow: 0 0 24px rgba(255,200,87,.10);
  animation: promptIn .25s ease both; white-space: nowrap;
}
#interact-prompt kbd { background: var(--gold); color: #2c1a02; border-color: #fff0b9; font-size: 11px; width: 23px; height: 23px; }
@keyframes promptIn { from { opacity: 0; transform: translate(-50%, 5px); } }

#hint-bar {
  position: absolute; left: 50%; bottom: calc(7px + var(--safe-bottom)); transform: translateX(-50%);
  font-size: 8px; font-weight: 500; color: rgba(210, 240, 235, .35); letter-spacing: .05em; white-space: nowrap;
}
#hint-bar b { color: rgba(230, 250, 246, .62); font-weight: 700; }
#hint-bar .dot { display: inline-block; width: 4px; height: 4px; background: var(--teal); border-radius: 50%; vertical-align: 1px; box-shadow: 0 0 5px var(--teal); }

/* Damage numbers */
#damage-layer { position: absolute; inset: 0; pointer-events: none; z-index: 30; overflow: hidden; }
.floaters {
  position: absolute; left: 0; top: 0; font-family: 'Bangers', cursive; font-size: 24px;
  color: #fff4cf; text-shadow: 0 2px 0 rgba(0,0,0,.32), 0 0 12px rgba(255, 190, 80, .6);
  letter-spacing: .04em; will-change: transform, opacity; white-space: nowrap;
}
.floaters.crit { color: #ffd24a; font-size: 32px; text-shadow: 0 2px 0 #7b3400, 0 0 18px rgba(255, 168, 40, .9); }
.floaters.heal { color: #8effb8; font-size: 22px; text-shadow: 0 0 12px rgba(80,255,150,.6); }
.floaters.hurt { color: #ff7d6e; font-size: 20px; text-shadow: 0 0 12px rgba(255,50,30,.6); }
.floaters.info { font-family: 'Outfit', sans-serif; font-size: 11px; font-weight: 800; letter-spacing: .12em; color: #ffd885; }
.floaters.xp { font-family: 'Outfit', sans-serif; font-size: 12px; font-weight: 800; color: #9ef1e0; }

/* Level up + zone banners */
#levelup-banner {
  position: absolute; left: 50%; top: 44%; transform: translate(-50%, -50%);
  text-align: center; pointer-events: none; z-index: 40; animation: levelPop 2.4s ease both;
}
.levelup-rays {
  position: absolute; left: 50%; top: 50%; width: 430px; height: 430px; transform: translate(-50%,-50%);
  background: conic-gradient(from 0deg, transparent 0 8deg, rgba(255, 204, 90, .13) 9deg 12deg, transparent 13deg 30deg);
  mask-image: radial-gradient(circle, #000 0 20%, transparent 68%);
  -webkit-mask-image: radial-gradient(circle, #000 0 20%, transparent 68%);
  animation: spin 9s linear infinite;
}
#levelup-banner span { display: block; font-size: 10px; font-weight: 800; letter-spacing: .42em; color: var(--gold); }
#levelup-banner b { display: block; font-family: 'Bangers', cursive; font-size: 90px; line-height: .95; color: #fff5d6; text-shadow: 0 0 30px rgba(255, 195, 60, .7), 0 5px 0 #8e5a18; }
#levelup-banner small { display: block; margin-top: 6px; font-size: 9px; font-weight: 700; letter-spacing: .18em; color: #d9f5ee; }
@keyframes levelPop {
  0% { opacity: 0; transform: translate(-50%,-50%) scale(.82); }
  12% { opacity: 1; transform: translate(-50%,-50%) scale(1.03); }
  20% { transform: translate(-50%,-50%) scale(1); }
  78% { opacity: 1; }
  100% { opacity: 0; transform: translate(-50%,-55%) scale(.98); }
}
#zone-banner {
  position: absolute; left: 50%; top: 33%; transform: translate(-50%,-50%); text-align: center;
  z-index: 38; pointer-events: none; animation: zoneIn 3.4s ease both;
}
#zone-banner span { font-size: 9px; font-weight: 800; letter-spacing: .44em; color: var(--gold); }
#zone-banner b { display: block; font-family: 'Bangers', cursive; font-weight: 400; font-size: clamp(40px, 6vw, 72px); letter-spacing: .1em; color: #fff5dd; text-shadow: 0 0 34px rgba(255, 180, 60, .42), 0 4px 0 rgba(30,15,2,.4); }
#zone-banner small { display: block; font-size: 10px; font-weight: 600; letter-spacing: .16em; color: rgba(220, 246, 240, .66); }
@keyframes zoneIn {
  0% { opacity: 0; transform: translate(-50%,-50%) scale(.96); }
  14%, 76% { opacity: 1; transform: translate(-50%,-50%) scale(1); }
  100% { opacity: 0; transform: translate(-50%,-54%) scale(1); }
}

/* Dialogue */
#dialogue {
  position: absolute; left: 50%; bottom: calc(125px + var(--safe-bottom)); transform: translateX(-50%);
  width: min(760px, 91vw); display: flex; gap: 14px; align-items: flex-start; z-index: 45;
  background: linear-gradient(135deg, rgba(8, 30, 36, .97), rgba(5, 21, 26, .92));
  border: 1px solid rgba(255, 200, 87, .25); border-top: 2px solid var(--gold);
  padding: 16px 18px; box-shadow: 0 24px 70px rgba(0,0,0,.55); backdrop-filter: blur(16px);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 12px), calc(100% - 12px) 100%, 0 100%);
  animation: dialogueIn .3s ease both;
}
@keyframes dialogueIn { from { opacity: 0; transform: translate(-50%, 10px); } }
.dialogue-portrait {
  width: 64px; height: 64px; border-radius: 50%; flex: none;
  background: radial-gradient(circle at 35% 28%, #ffd697, #d0593d 45%, #63251d);
  border: 2px solid rgba(255, 200, 87, .55); display: grid; place-items: center;
  font-family: 'Bangers', cursive; font-size: 33px; color: #fff4d8; text-shadow: 0 2px 4px rgba(50,10,0,.5);
  box-shadow: 0 0 20px rgba(255, 150, 60, .2);
}
.dialogue-body { flex: 1; min-width: 0; }
.dialogue-name { font-family: 'Bangers', cursive; font-size: 22px; letter-spacing: .08em; color: #ffe6a6; }
.dialogue-name span { font-family: 'Outfit', sans-serif; font-size: 8px; font-weight: 800; letter-spacing: .22em; color: rgba(200, 235, 228, .44); margin-left: 6px; }
#dialogue-text { margin: 5px 0 11px; font-size: 13px; line-height: 1.5; color: #d5eae6; min-height: 38px; }
.dialogue-actions { display: flex; gap: 8px; flex-wrap: wrap; }
.dialogue-actions button {
  background: rgba(46, 217, 195, .12); border: 1px solid rgba(46, 217, 195, .32);
  color: #d8fff7; font-size: 10px; font-weight: 800; letter-spacing: .10em;
  padding: 7px 15px; border-radius: 3px; transition: background .15s, border-color .15s;
}
.dialogue-actions button:hover { background: rgba(46, 217, 195, .24); border-color: var(--teal); }
.dialogue-actions button.primary { background: rgba(255, 200, 87, .16); border-color: rgba(255, 200, 87, .55); color: #ffeabb; }
.dialogue-actions button.primary:hover { background: rgba(255, 200, 87, .28); }
.dialogue-close { position: absolute; right: 8px; top: 7px; border: 0; background: transparent; color: rgba(220,245,240,.5); font-size: 13px; }

/* Touch */
#touch-controls { display: none; position: absolute; inset: 0; z-index: 22; pointer-events: none; }
#joystick { position: absolute; left: calc(20px + var(--safe-left)); bottom: calc(24px + var(--safe-bottom)); width: 140px; height: 140px; pointer-events: auto; }
.joy-base {
  position: absolute; inset: 0; border-radius: 50%;
  border: 1px solid rgba(190, 245, 237, .22); background: radial-gradient(circle, rgba(9,38,44,.25), rgba(4,20,25,.62));
  box-shadow: inset 0 0 30px rgba(0,0,0,.35);
}
.joy-base::before, .joy-base::after { content: ''; position: absolute; border-radius: 50%; border: 1px solid rgba(255,255,255,.06); }
.joy-base::before { inset: 17px; }
.joy-base::after { inset: 36px; }
.joy-knob {
  position: absolute; left: 50%; top: 50%; width: 58px; height: 58px; margin: -29px 0 0 -29px;
  border-radius: 50%; background: radial-gradient(circle at 35% 30%, rgba(220,255,249,.36), rgba(46,217,195,.28) 55%, rgba(7,60,62,.78));
  border: 1px solid rgba(170, 255, 245, .46); box-shadow: 0 5px 20px rgba(0,0,0,.35), 0 0 18px rgba(46,217,195,.18);
  transition: transform .05s linear;
}
#touch-actions { position: absolute; right: calc(18px + var(--safe-right)); bottom: calc(22px + var(--safe-bottom)); width: 214px; height: 196px; pointer-events: none; }
.touch-btn {
  position: absolute; pointer-events: auto; border-radius: 50%;
  border: 1px solid rgba(190, 245, 237, .27); color: #e8fffa;
  background: radial-gradient(circle at 35% 30%, rgba(89, 197, 185, .30), rgba(5, 28, 34, .78));
  display: grid; place-items: center; font-weight: 800; font-size: 15px;
  box-shadow: 0 6px 18px rgba(0,0,0,.32), inset 0 0 20px rgba(46,217,195,.06);
  backdrop-filter: blur(8px); touch-action: none;
}
.touch-btn:active { transform: scale(.94); background: rgba(46, 217, 195, .36); }
.touch-btn svg { width: 25px; height: 25px; fill: #e9fffb; }
.touch-btn.attack { right: 0; bottom: 0; width: 82px; height: 82px; border-color: rgba(255,200,87,.45); background: radial-gradient(circle at 35% 30%, rgba(255,200,87,.32), rgba(52,30,8,.82)); }
.touch-btn.attack svg { width: 34px; height: 34px; fill: #ffe5a6; }
.touch-btn.skill { right: 88px; bottom: 8px; width: 58px; height: 58px; border-color: rgba(255,150,80,.45); color: #ffd7a8; }
.touch-btn.ultimate { right: 102px; bottom: 78px; width: 48px; height: 48px; border-color: rgba(255,120,80,.4); color: #ffbea2; }
.touch-btn.dash { right: 12px; bottom: 91px; width: 50px; height: 50px; }
.touch-btn.jump { right: 45px; bottom: 150px; width: 44px; height: 44px; font-size: 20px; }
.touch-btn.interact { right: 0; bottom: 148px; width: 44px; height: 44px; border-color: rgba(255,200,87,.5); color: #ffe3a0; font-size: 13px; }
body.touch-device #touch-controls { display: block; }
body.touch-device #hint-bar, body.touch-device #fruit-switcher, body.touch-device #hotbar { display: none; }
body.touch-device #compass-wrap { width: 240px; opacity: .8; }
body.touch-device .slot-key { display: none; }

/* ------------------------------------------------------------------ */
/* Start screen                                                        */
/* ------------------------------------------------------------------ */
#start-screen {
  position: absolute; inset: 0; z-index: 70; display: flex; flex-direction: column;
  justify-content: space-between; padding: calc(22px + var(--safe-top)) calc(34px + var(--safe-right)) calc(20px + var(--safe-bottom)) calc(34px + var(--safe-left));
  background:
    radial-gradient(ellipse at 24% 46%, rgba(3, 17, 22, .12) 0%, rgba(3, 15, 20, .50) 54%, rgba(2, 12, 16, .86) 100%),
    linear-gradient(90deg, rgba(3, 16, 21, .80) 0%, rgba(3, 16, 21, .28) 44%, transparent 70%),
    linear-gradient(0deg, rgba(3, 14, 18, .88) 0%, transparent 38%);
  transition: opacity .6s ease, visibility .6s;
}
#start-screen.leaving { opacity: 0; visibility: hidden; pointer-events: none; }
.start-bg { position: absolute; inset: 0; pointer-events: none; }
.start-top { display: flex; justify-content: space-between; align-items: flex-start; position: relative; z-index: 2; }
.brand-mark { display: flex; align-items: center; gap: 9px; font-size: 8.5px; font-weight: 800; letter-spacing: .26em; color: rgba(230, 250, 246, .62); }
.brand-orb { width: 20px; height: 20px; border-radius: 50%; background: radial-gradient(circle at 34% 30%, #ffe6a5, #ffc857 50%, #b2741d); display: grid; place-items: center; color: #4a2c04; font-size: 10px; box-shadow: 0 0 14px rgba(255,200,87,.4); }
.build-chip { font-size: 8px; font-weight: 800; letter-spacing: .20em; color: rgba(220, 245, 240, .38); border: 1px solid rgba(200,240,235,.12); padding: 5px 9px; border-radius: 3px; }
.start-main { position: relative; z-index: 2; max-width: 670px; margin-top: -4vh; }
.eyebrow { display: flex; align-items: center; gap: 12px; font-size: 8.5px; font-weight: 800; letter-spacing: .34em; color: var(--gold); margin-bottom: 9px; }
.eyebrow span { width: 28px; height: 1px; background: linear-gradient(90deg, transparent, var(--gold)); }
.eyebrow span:last-child { background: linear-gradient(90deg, var(--gold), transparent); }
.start-main h1 {
  margin: 0; font-family: 'Bangers', cursive; font-weight: 400;
  font-size: clamp(78px, 12.5vw, 166px); line-height: .78; letter-spacing: .025em;
  color: #fff6df; text-shadow: 0 5px 0 rgba(92, 50, 11, .38), 0 0 60px rgba(255, 174, 56, .20);
}
.title-fruit {
  background: linear-gradient(180deg, #fff8df 4%, #ffd473 42%, #f39a2f 100%);
  -webkit-background-clip: text; background-clip: text; color: transparent;
  -webkit-text-stroke: 1px rgba(255, 235, 180, .12); filter: drop-shadow(0 4px 0 rgba(116, 56, 8, .28));
}
.title-bound {
  background: linear-gradient(180deg, #f2fffb 6%, #86f4e2 42%, #23aeb0 100%);
  -webkit-background-clip: text; background-clip: text; color: transparent;
  filter: drop-shadow(0 4px 0 rgba(3, 65, 68, .32));
}
.subtitle { display: flex; align-items: center; gap: 13px; font-family: 'Bangers', cursive; font-size: clamp(20px, 2.6vw, 32px); letter-spacing: .28em; color: #ffe7ac; margin: 14px 0 0 3px; }
.subtitle i { width: 45px; height: 1px; background: linear-gradient(90deg, transparent, rgba(255,200,87,.62)); }
.subtitle i:last-child { background: linear-gradient(90deg, rgba(255,200,87,.62), transparent); }
.tagline { margin: 18px 0 26px 4px; font-size: clamp(12px, 1.25vw, 15px); line-height: 1.6; color: rgba(220, 243, 238, .78); font-weight: 400; max-width: 470px; }
.start-actions { display: flex; gap: 12px; align-items: stretch; margin-left: 3px; }
.play-btn {
  position: relative; display: flex; align-items: center; gap: 13px; text-align: left;
  background: linear-gradient(135deg, #ffcf62, #f0a52f 58%, #c87a18);
  color: #281703; border: 1px solid #ffe7a8; padding: 13px 26px 13px 14px;
  clip-path: polygon(0 0, 100% 0, calc(100% - 12px) 100%, 0 100%);
  box-shadow: 0 14px 36px rgba(190, 105, 12, .32), inset 0 1px 0 rgba(255,255,255,.45);
  transition: transform .15s, filter .15s;
}
.play-btn:hover { transform: translateY(-2px); filter: brightness(1.07); }
.play-btn:active { transform: translateY(0) scale(.99); }
.play-icon { font-size: 19px; width: 34px; height: 34px; display: grid; place-items: center; border-radius: 50%; background: rgba(58, 28, 2, .16); border: 1px solid rgba(68, 32, 2, .18); }
.play-btn b { display: block; font-family: 'Bangers', cursive; font-size: 23px; font-weight: 400; letter-spacing: .10em; line-height: 1; }
.play-btn small { display: block; font-size: 8px; font-weight: 700; letter-spacing: .12em; opacity: .66; margin-top: 2px; }
.play-btn.small { font-size: 12px; padding: 10px 20px 10px 10px; }
.play-btn.small b { font-size: 19px; }
.play-btn.small .play-icon { width: 30px; height: 30px; font-size: 16px; }
.ghost-btn {
  background: rgba(7, 28, 34, .58); border: 1px solid rgba(160, 234, 226, .22); color: #c8eee8;
  font-size: 10px; font-weight: 800; letter-spacing: .18em; padding: 0 20px; border-radius: 3px;
  backdrop-filter: blur(8px); transition: background .15s, border-color .15s; clip-path: polygon(0 0, 100% 0, calc(100% - 10px) 100%, 0 100%);
}
.ghost-btn:hover { background: rgba(46,217,195,.15); border-color: rgba(46,217,195,.55); }
.ghost-btn.danger { color: #ffb4a4; border-color: rgba(255,106,77,.3); }
.ghost-btn.danger:hover { background: rgba(255,106,77,.14); border-color: rgba(255,106,77,.6); }
.start-features { display: flex; gap: 22px; margin: 24px 0 0 4px; font-size: 9px; font-weight: 600; letter-spacing: .08em; color: rgba(210, 242, 236, .46); }
.start-features b { font-family: 'Bangers', cursive; font-size: 18px; font-weight: 400; color: var(--gold); margin-right: 4px; vertical-align: -1px; }
.start-bottom { position: relative; z-index: 2; }
.controls-strip {
  display: flex; flex-wrap: wrap; gap: 10px 18px; align-items: center;
  border-top: 1px solid rgba(180, 240, 232, .10); padding-top: 11px; max-width: 920px;
}
.controls-strip span { display: flex; align-items: center; gap: 5px; font-size: 8.5px; font-weight: 600; color: rgba(210, 242, 236, .46); letter-spacing: .05em; }
.controls-strip kbd { font-size: 8px; }
.start-note { margin-top: 10px; font-size: 8px; line-height: 1.6; color: rgba(210, 242, 236, .28); letter-spacing: .04em; }
.start-deco { position: absolute; border-radius: 50%; pointer-events: none; filter: blur(2px); opacity: .5; }
.fruit-deco { width: 270px; height: 270px; right: 8vw; top: 20vh; border: 1px solid rgba(255, 200, 87, .13); box-shadow: inset 0 0 60px rgba(255, 170, 50, .05); }
.fruit-deco::before { content: ''; position: absolute; inset: 30px; border-radius: 50%; border: 1px dashed rgba(120, 240, 225, .12); animation: spin 34s linear infinite; }
.fruit-deco::after { content: '✦'; position: absolute; left: 50%; top: 50%; transform: translate(-50%,-50%); font-size: 54px; color: rgba(255, 200, 87, .18); }
.fruit-deco.d2 { width: 430px; height: 430px; right: -90px; top: 8vh; opacity: .3; }

/* ------------------------------------------------------------------ */
/* Death / victory / pause / map / help                                */
/* ------------------------------------------------------------------ */
#death-screen, #victory-screen, #pause-menu, #map-overlay, #help-overlay {
  position: absolute; inset: 0; z-index: 80; display: grid; place-items: center;
  background: radial-gradient(ellipse at center, rgba(3, 15, 19, .62), rgba(1, 8, 11, .94));
  backdrop-filter: blur(7px);
}
.death-inner, .victory-inner, .pause-inner {
  text-align: center; width: min(560px, 90vw); padding: 32px;
  background: linear-gradient(170deg, rgba(10, 34, 40, .92), rgba(4, 18, 22, .94));
  border: 1px solid var(--line); border-top: 2px solid var(--coral);
  box-shadow: 0 30px 90px rgba(0,0,0,.6); position: relative;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 18px), calc(100% - 18px) 100%, 0 100%);
}
.death-kicker, .victory-kicker, .pause-kicker { font-size: 8px; font-weight: 800; letter-spacing: .35em; color: var(--coral); }
.death-inner h2, .victory-inner h2, .pause-inner h2 {
  font-family: 'Bangers', cursive; font-weight: 400; font-size: clamp(46px, 6vw, 70px);
  line-height: .92; letter-spacing: .05em; margin: 9px 0 10px; color: #fff3dc;
}
.death-inner p, .victory-inner p { font-size: 12px; line-height: 1.6; color: #bcd8d4; max-width: 390px; margin: 0 auto 18px; }
.death-inner p b { color: var(--gold); }
.death-count { display: flex; align-items: baseline; justify-content: center; gap: 6px; margin-bottom: 16px; }
.death-count b { font-family: 'Bangers', cursive; font-size: 42px; color: var(--gold); }
.death-count span { font-size: 9px; letter-spacing: .18em; color: rgba(220,245,240,.5); }
.death-inner .play-btn, .victory-inner .play-btn, .pause-inner .play-btn { margin: 6px auto 0; }
.victory-inner { border-top-color: var(--gold); }
.victory-kicker { color: var(--gold); }
.victory-inner h2 em { font-style: normal; color: var(--gold); text-shadow: 0 0 36px rgba(255,200,60,.4); }
.victory-rewards { display: flex; justify-content: center; gap: 12px; margin: 6px 0 20px; }
.victory-rewards div { flex: 1; max-width: 130px; padding: 10px 6px; border: 1px solid var(--line); background: rgba(255,255,255,.03); }
.victory-rewards span { display: block; font-family: 'Bangers', cursive; font-size: 21px; color: var(--gold); letter-spacing: .04em; }
.victory-rewards small { display: block; margin-top: 2px; font-size: 7px; font-weight: 800; letter-spacing: .18em; color: rgba(220,245,240,.4); }
.pause-inner { border-top-color: var(--teal); }
.pause-kicker { color: var(--teal); }
.pause-stats { display: flex; justify-content: center; gap: 14px; margin: 2px 0 20px; }
.pause-stats div { min-width: 96px; }
.pause-stats small { display: block; font-size: 7px; font-weight: 800; letter-spacing: .2em; color: rgba(220,245,240,.4); }
.pause-stats b { font-family: 'Bangers', cursive; font-size: 29px; font-weight: 400; color: #fff3d7; }
.pause-inner .ghost-btn { margin-top: 11px; height: 38px; }
.pause-hint { font-size: 8px; letter-spacing: .08em; color: rgba(220,245,240,.3); margin-top: 16px; }

.map-panel, .help-panel {
  width: min(1060px, 94vw); padding: 18px 20px 16px;
  background: linear-gradient(170deg, rgba(8, 31, 38, .96), rgba(3, 16, 20, .97));
  border: 1px solid var(--line); border-top: 2px solid var(--gold);
  box-shadow: 0 30px 100px rgba(0,0,0,.65);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 20px), calc(100% - 20px) 100%, 0 100%);
}
.map-head { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 10px; }
.map-head span { font-size: 8px; font-weight: 800; letter-spacing: .3em; color: var(--gold); }
.map-head h2 { margin: 3px 0 0; font-family: 'Bangers', cursive; font-weight: 400; font-size: 34px; letter-spacing: .10em; color: #fff3d8; }
.map-head .icon-btn { width: 32px; height: 32px; font-size: 14px; color: #d8f5ef; }
#world-map { width: 100%; aspect-ratio: 1200 / 680; border: 1px solid rgba(160, 235, 225, .10); background: #06222b; }
.map-legend { display: flex; align-items: center; gap: 17px; margin-top: 10px; font-size: 8px; font-weight: 700; letter-spacing: .09em; color: rgba(220,245,240,.52); }
.map-legend span { display: flex; align-items: center; gap: 5px; }
.lg { width: 7px; height: 7px; border-radius: 50%; display: inline-block; }
.lg.you { background: var(--gold); box-shadow: 0 0 6px var(--gold); }
.lg.quest { background: var(--teal); }
.lg.danger { background: var(--coral); }
.lg.boss { background: #ff4d1a; box-shadow: 0 0 7px #ff4d1a; }
.map-coords { margin-left: auto; font-size: 8px; color: rgba(255,200,87,.58); letter-spacing: .12em; }
.help-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px 16px; margin-top: 6px; }
.help-grid div { display: flex; align-items: center; gap: 9px; border-bottom: 1px solid rgba(160,235,225,.07); padding: 7px 2px; }
.help-grid kbd { min-width: 62px; justify-content: center; }
.help-grid span { font-size: 10px; color: rgba(220,245,240,.65); }
.help-tip { margin: 13px 0 1px; font-size: 9px; line-height: 1.5; color: rgba(220,245,240,.36); }

/* Loading */
#loading {
  position: absolute; inset: 0; z-index: 100; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 12px;
  background: radial-gradient(circle at 50% 45%, #0c3540, #041419 70%); transition: opacity .7s ease, visibility .7s;
}
#loading.done { opacity: 0; visibility: hidden; pointer-events: none; }
.load-mark { width: 58px; height: 58px; border-radius: 50%; background: radial-gradient(circle at 34% 28%, #ffe8ae, #ffc857 48%, #b56b1d); display: grid; place-items: center; color: #482a04; font-size: 25px; box-shadow: 0 0 40px rgba(255,200,87,.3); animation: pulseMark 1.8s ease-in-out infinite; }
@keyframes pulseMark { 50% { transform: scale(1.08); box-shadow: 0 0 65px rgba(255,200,87,.5); } }
.load-text { font-size: 9px; font-weight: 800; letter-spacing: .4em; color: rgba(220,245,240,.55); }
.load-bar { width: 190px; height: 2px; background: rgba(255,255,255,.1); overflow: hidden; }
.load-bar i { display: block; height: 100%; width: 38%; background: linear-gradient(90deg, transparent, var(--gold), transparent); animation: loadSlide 1.5s ease-in-out infinite; }
@keyframes loadSlide { from { transform: translateX(-120%); } to { transform: translateX(340%); } }

/* ------------------------------------------------------------------ */
/* Responsive                                                          */
/* ------------------------------------------------------------------ */
@media (max-width: 980px) {
  #compass-wrap { width: 260px; }
  #quest-tracker { width: 238px; }
  .status-bars { width: 190px; }
  #top-left { left: 16px; }
  #minimap-wrap, #quest-tracker { right: 16px; }
  .mini-frame { width: 148px; height: 148px; }
  #quest-tracker { top: 192px; }
  .start-main { max-width: 560px; }
  .start-features { gap: 14px; }
}
@media (max-width: 700px) {
  #top-left { top: calc(12px + var(--safe-top)); left: calc(12px + var(--safe-left)); gap: 6px; }
  .player-card { min-width: 0; padding: 6px 12px 6px 6px; gap: 8px; }
  .level-badge { width: 38px; height: 38px; }
  .level-badge b { font-size: 20px; }
  .player-name { font-size: 19px; }
  .player-name em { font-size: 6px; }
  .bounty-row { font-size: 9.5px; }
  .wallet { font-size: 10px; padding: 3px 6px; }
  .coin-icon { width: 15px; height: 15px; font-size: 8px; }
  #compass-wrap { display: none; }
  #minimap-wrap { top: calc(12px + var(--safe-top)); right: calc(10px + var(--safe-right)); }
  .mini-frame { width: 110px; height: 110px; }
  .mini-compass.n { top: -14px; } .mini-compass.s { bottom: -14px; }
  .mini-compass.e { right: -11px; } .mini-compass.w { left: -11px; }
  .map-btn { bottom: -18px; font-size: 6.5px; padding: 3px 6px; }
  .map-btn kbd { display: none; }
  #quest-tracker { top: calc(142px + var(--safe-top)); right: calc(10px + var(--safe-right)); width: 172px; padding: 8px 9px 8px 10px; }
  #quest-title { font-size: 17px; margin: 5px 0 3px; }
  #quest-objective { font-size: 9px; min-height: 24px; line-height: 1.3; }
  .quest-head { font-size: 6.5px; }
  .quest-foot { font-size: 7px; }
  #bottom-left { left: calc(12px + var(--safe-left)); bottom: calc(170px + var(--safe-bottom)); }
  .status-card { padding: 6px 9px 6px 6px; gap: 6px; }
  .fruit-orb { width: 38px; height: 38px; }
  .fruit-orb b { font-size: 19px; }
  .status-bars { width: 122px; }
  .bar { height: 10px; }
  .bar span { font-size: 6px; }
  .xp-row { display: none; }
  .bar-label { font-size: 6px; width: 11px; }
  #hotbar { display: none; }
  #interact-prompt { bottom: calc(224px + var(--safe-bottom)); font-size: 9px; padding: 5px 10px 5px 5px; }
  #hint-bar { display: none; }
  #toast-stack { top: calc(64px + var(--safe-top)); width: 74vw; }
  .toast { font-size: 9px; padding: 6px 10px; }
  #boss-bar { top: calc(62px + var(--safe-top)); width: 72vw; }
  .boss-name { font-size: 18px; }
  .boss-name span { font-size: 6px; }
  #crosshair { opacity: .3; }
  .start-main { margin-top: 0; }
  .start-main h1 { font-size: clamp(64px, 22vw, 122px); }
  .tagline { font-size: 11px; max-width: 330px; margin-bottom: 18px; }
  .subtitle { font-size: 18px; letter-spacing: .2em; }
  .controls-strip { display: none; }
  .start-features { margin-top: 18px; gap: 12px; font-size: 8px; }
  .start-note { font-size: 7px; max-width: 290px; }
  .start-main .eyebrow { font-size: 7px; letter-spacing: .2em; }
  .play-btn { padding: 10px 18px 10px 10px; }
  .play-btn b { font-size: 19px; }
  .start-actions { flex-wrap: wrap; }
  #dialogue { bottom: calc(240px + var(--safe-bottom)); width: calc(100vw - 24px); padding: 11px 12px; gap: 9px; }
  .dialogue-portrait { width: 42px; height: 42px; font-size: 22px; }
  .dialogue-name { font-size: 16px; }
  #dialogue-text { font-size: 10px; line-height: 1.4; min-height: 28px; }
  .dialogue-actions button { font-size: 8px; padding: 5px 10px; }
  .map-panel, .help-panel { width: calc(100vw - 20px); padding: 12px; }
  .map-head h2 { font-size: 26px; }
  .help-grid { grid-template-columns: 1fr 1fr; gap: 4px 10px; }
  .help-grid kbd { min-width: 48px; font-size: 8px; }
  .help-grid span { font-size: 8px; }
  .map-legend { gap: 9px; flex-wrap: wrap; font-size: 7px; }
  .victory-rewards { gap: 6px; }
  .victory-rewards span { font-size: 15px; }
  .death-inner, .victory-inner, .pause-inner { padding: 24px 18px; }
  #zone-banner { top: 29%; }
  .fruit-deco { display: none; }
}
@media (max-height: 520px) and (orientation: landscape) {
  .start-main { margin-top: 0; }
  .start-main h1 { font-size: clamp(54px, 15vh, 100px); }
  .tagline { margin: 10px 0 12px; font-size: 10px; }
  .start-features, .start-note { display: none; }
  .start-bottom { display: none; }
  #start-screen { padding-top: 12px; }
  .start-top { display: none; }
  .start-main { max-width: 58vw; }
  .start-deco { display: none; }
  .map-panel { height: 94vh; overflow: auto; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; }
}

import { clamp, TAU } from './noise.js';

const $ = id => document.getElementById(id);

const FRUIT_DATA = {
  ember: { name: 'Ember', glyph: '✦', skill: 'EMBER BALL', ultimate: 'INFERNO', color: '#ff7a2a', cost: 20, ultCost: 45 },
  gale: { name: 'Gale', glyph: '≋', skill: 'WIND SLASH', ultimate: 'CYCLONE', color: '#4cf0d6', cost: 18, ultCost: 42 },
  tide: { name: 'Tide', glyph: '◉', skill: 'TIDAL WAVE', ultimate: 'MAELSTROM', color: '#6db7ff', cost: 22, ultCost: 48 },
};

export class UI {
  constructor() {
    this.el = {
      start: $('start-screen'), hud: $('hud'), loading: $('loading'),
      level: $('level-value'), bounty: $('bounty-value'), beli: $('beli-value'), title: $('player-title'),
      hp: $('hp-fill'), hpText: $('hp-text'), energy: $('energy-fill'), energyText: $('energy-text'),
      xp: $('xp-fill'), xpText: $('xp-text'),
      questTitle: $('quest-title'), questObjective: $('quest-objective'), questFill: $('quest-fill'),
      questProgress: $('quest-progress-text'), questDistance: $('quest-distance'), questChapter: $('quest-chapter'),
      bossBar: $('boss-bar'), bossName: $('boss-name'), bossRank: $('boss-rank'), bossFill: $('boss-fill'), bossText: $('boss-hp-text'),
      toasts: $('toast-stack'), interact: $('interact-prompt'), interactText: $('interact-text'),
      dialogue: $('dialogue'), dialogueName: $('dialogue-name'), dialogueText: $('dialogue-text'),
      dialogueActions: $('dialogue-actions'), dialoguePortrait: $('dialogue-portrait'),
      levelup: $('levelup-banner'), levelupLevel: $('levelup-level'),
      zone: $('zone-banner'), zoneName: $('zone-banner-name'), zoneSub: $('zone-banner-sub'), zoneCurrent: $('zone-name'),
      death: $('death-screen'), deathLoss: $('death-loss'), deathCount: $('death-count'),
      victory: $('victory-screen'), pause: $('pause-menu'), map: $('map-overlay'), help: $('help-overlay'),
      minimap: $('minimap'), worldMap: $('world-map'),
      flash: $('flash'), hitVignette: $('vignette-hit'),
      skillName: $('skill-name'), ultimateName: $('ultimate-name'), skillCost: $('skill-cost'), ultimateCost: $('ultimate-cost'),
      slotSkill: $('slot-skill'), slotUltimate: $('slot-ultimate'), slotAttack: $('slot-attack'), slotDash: $('slot-dash'),
      fruitOrb: $('fruit-orb'), fruitGlyph: $('fruit-glyph'), fruitChips: [...document.querySelectorAll('.fruit-chip')],
      pauseLevel: $('pause-level'), pauseBounty: $('pause-bounty'), pauseBeli: $('pause-beli'),
      mapCoords: $('map-coords'), muteBtn: $('mute-btn'),
    };
    this.miniCtx = this.el.minimap.getContext('2d');
    this.mapCtx = this.el.worldMap.getContext('2d');
    this.isTouch = matchMedia('(pointer: coarse)').matches || navigator.maxTouchPoints > 1;
    if (this.isTouch) document.body.classList.add('touch-device');
    this.touchQueue = [];
    this.touchMove = { x: 0, y: 0 };
    this.toastItems = [];
    this.dialogueTimer = null;
    this.lastHud = {};
    this.heading = 90;
    this.compassLabels = [...document.querySelectorAll('.compass-labels span')].map((el, i) => ({ el, angle: i * 45 }));
    this.initTouch();
  }

  /* ----------------------------- lifecycle ----------------------------- */
  start() {
    this.el.start.classList.add('leaving');
    setTimeout(() => this.el.start.classList.add('hidden'), 650);
    this.el.hud.classList.remove('hidden');
    this.el.loading.classList.add('done');
  }

  ready() { this.el.loading.classList.add('done'); }

  showLoading() { this.el.loading.classList.remove('done'); }

  /* ------------------------------- stats ------------------------------- */
  setPlayer({ level, bounty, beli, title }) {
    if (level !== undefined && level !== this.lastHud.level) {
      this.el.level.textContent = level;
      this.lastHud.level = level;
    }
    if (bounty !== undefined) this.el.bounty.textContent = this.formatNumber(bounty);
    if (beli !== undefined) this.el.beli.textContent = this.formatNumber(beli);
    if (title !== undefined) this.el.title.textContent = title;
    this.el.pauseLevel.textContent = level ?? this.el.pauseLevel.textContent;
    this.el.pauseBounty.textContent = this.formatNumber(bounty ?? 0);
    this.el.pauseBeli.textContent = this.formatNumber(beli ?? 0);
  }

  setHealth(hp, max) {
    const pct = clamp(hp / max, 0, 1) * 100;
    this.el.hp.style.width = `${pct}%`;
    this.el.hpText.textContent = `${Math.ceil(Math.max(hp, 0))} / ${max}`;
    this.el.hpText.style.color = pct < 28 ? '#ffe5df' : '';
    if (pct < 25 && !this.lowHp) {
      this.lowHp = true;
    } else if (pct >= 25) this.lowHp = false;
  }

  setEnergy(en, max) {
    const pct = clamp(en / max, 0, 1) * 100;
    this.el.energy.style.width = `${pct}%`;
    this.el.energyText.textContent = `${Math.ceil(Math.max(en, 0))} / ${max}`;
  }

  setXP(xp, max) {
    this.el.xp.style.width = `${clamp(xp / max, 0, 1) * 100}%`;
    this.el.xpText.textContent = `${Math.floor(xp)} / ${max} XP`;
  }

  setZone(name) { this.el.zoneCurrent.textContent = name.toUpperCase(); }

  /* ------------------------------- quest ------------------------------- */
  setQuest({ title, objective, progress = 0, total = 0, chapter = 'CH. 1', distance = null, showProgress = true }) {
    this.el.questTitle.textContent = title;
    this.el.questObjective.textContent = objective;
    this.el.questChapter.textContent = chapter;
    this.el.questFill.style.width = total > 0 ? `${clamp(progress / total, 0, 1) * 100}%` : '0%';
    this.el.questProgress.textContent = total > 0 ? `${progress} / ${total}` : '—';
    this.el.questDistance.textContent = distance == null ? '— m' : `${Math.round(distance)} m`;
    this.el.questProgress.style.opacity = showProgress ? '' : '.28';
  }

  setQuestDistance(distance) {
    if (distance == null) { this.el.questDistance.textContent = '— m'; return; }
    this.el.questDistance.textContent = `${Math.round(distance)} m`;
  }

  /* -------------------------------- boss ------------------------------- */
  setBoss({ visible, name = 'ASHBEARD', rank = 'CAPTAIN', hp = 1, subtitle = '' }) {
    this.el.bossBar.classList.toggle('hidden', !visible);
    if (!visible) return;
    this.el.bossName.textContent = name;
    this.el.bossRank.textContent = rank;
    this.el.bossFill.style.width = `${clamp(hp, 0, 1) * 100}%`;
    this.el.bossText.textContent = `${Math.ceil(clamp(hp, 0, 1) * 100)}%`;
  }

  /* ------------------------------ toasts ------------------------------- */
  toast(text, { kind = 'default', icon = '✦', time = 3600 } = {}) {
    const el = document.createElement('div');
    el.className = `toast ${kind}`;
    el.innerHTML = `<span class="t-icon">${icon}</span><span>${text}</span>`;
    this.el.toasts.appendChild(el);
    this.toastItems.push(el);
    while (this.toastItems.length > 4) {
      const old = this.toastItems.shift();
      old.remove();
    }
    setTimeout(() => {
      el.classList.add('out');
      setTimeout(() => {
        el.remove();
        this.toastItems = this.toastItems.filter(t => t !== el);
      }, 320);
    }, time);
  }

  /* ----------------------------- interaction --------------------------- */
  setInteract(text) {
    if (!text) { this.el.interact.classList.add('hidden'); return; }
    this.el.interact.classList.remove('hidden');
    this.el.interactText.innerHTML = text;
  }

  /* ------------------------------ dialogue ----------------------------- */
  showDialogue({ name, role, text, options = [], portrait = 'R', portraitColor = '' }) {
    this.el.dialogue.classList.remove('hidden');
    this.el.dialogueName.innerHTML = `${name} <span>${role || ''}</span>`;
    this.el.dialoguePortrait.textContent = portrait;
    this.el.dialoguePortrait.style.background = portraitColor || '';
    this.el.dialogueText.textContent = '';
    this.el.dialogueActions.innerHTML = '';
    if (this.dialogueTimer) clearInterval(this.dialogueTimer);
    let i = 0;
    const input = text;
    this.dialogueTimer = setInterval(() => {
      i += 2;
      this.el.dialogueText.textContent = input.slice(0, i);
      if (i >= input.length) { clearInterval(this.dialogueTimer); this.dialogueTimer = null; }
    }, 12);
    options.forEach((opt, index) => {
      const btn = document.createElement('button');
      btn.textContent = opt.label;
      if (opt.primary) btn.className = 'primary';
      btn.addEventListener('click', () => {
        this.hideDialogue();
        opt.onClick?.();
      });
      this.el.dialogueActions.appendChild(btn);
    });
  }

  hideDialogue() {
    this.el.dialogue.classList.add('hidden');
    if (this.dialogueTimer) clearInterval(this.dialogueTimer);
    this.dialogueTimer = null;
  }

  get dialogueOpen() { return !this.el.dialogue.classList.contains('hidden'); }

  /* ------------------------------- hotbar ------------------------------ */
  setFruit(fruitKey, unlocked = ['ember'], level = 1) {
    const data = FRUIT_DATA[fruitKey] || FRUIT_DATA.ember;
    this.el.skillName.textContent = data.skill;
    this.el.ultimateName.textContent = data.ultimate;
    this.el.skillCost.textContent = data.cost;
    this.el.ultimateCost.textContent = data.ultCost;
    this.el.fruitGlyph.textContent = data.glyph;
    this.el.fruitOrb.style.background = `radial-gradient(circle at 34% 26%, #ffe5b0, ${data.color} 44%, #6d1b0d 80%, #3a0b05)`;
    this.el.slotUltimate.classList.toggle('locked-ult', level < 5);
    this.el.fruitChips.forEach(chip => {
      const key = chip.dataset.fruit;
      chip.classList.toggle('active', key === fruitKey);
      chip.classList.toggle('locked', !unlocked.includes(key));
      const lock = chip.querySelector('.lock');
      if (lock) lock.style.display = unlocked.includes(key) ? 'none' : 'block';
    });
    this.lastHud.fruit = fruitKey;
  }

  setCooldowns({ dash = 0, dashMax = 1, skill = 0, skillMax = 1, ultimate = 0, ultimateMax = 1 }) {
    const set = (slot, remaining, max) => {
      const cd = slot.querySelector('.cooldown');
      const text = slot.querySelector('.cd-text');
      const ratio = max > 0 ? clamp(remaining / max, 0, 1) : 0;
      cd.style.transform = `scaleY(${ratio})`;
      if (text) {
        text.textContent = remaining > 0.08 ? (remaining < 1 ? remaining.toFixed(1) : Math.ceil(remaining)) : '';
        text.style.opacity = ratio > 0.02 ? '1' : '0';
      }
    };
    set(this.el.slotDash, dash, dashMax);
    set(this.el.slotSkill, skill, skillMax);
    set(this.el.slotUltimate, ultimate, ultimateMax);
  }

  pulseSlot(which) {
    const slot = { attack: this.el.slotAttack, dash: this.el.slotDash, skill: this.el.slotSkill, ultimate: this.el.slotUltimate }[which];
    if (!slot) return;
    slot.classList.add('active');
    slot.classList.remove('pulse');
    void slot.offsetWidth;
    slot.classList.add('pulse');
    setTimeout(() => slot.classList.remove('active'), 140);
  }

  /* ------------------------------- banners ----------------------------- */
  levelUp(level) {
    this.el.levelupLevel.textContent = level;
    this.el.levelup.classList.remove('hidden');
    const el = this.el.levelup;
    el.style.animation = 'none';
    void el.offsetWidth;
    el.style.animation = '';
    setTimeout(() => this.el.levelup.classList.add('hidden'), 2500);
  }

  showZone(name, subtitle) {
    this.el.zoneName.textContent = name.toUpperCase();
    this.el.zoneSub.textContent = subtitle || '';
    this.el.zone.classList.remove('hidden');
    const el = this.el.zone;
    el.style.animation = 'none';
    void el.offsetWidth;
    el.style.animation = '';
    setTimeout(() => this.el.zone.classList.add('hidden'), 3500);
    this.setZone(name);
  }

  /* ------------------------------- flash ------------------------------- */
  hurtFlash() {
    this.el.hitVignette.style.opacity = '1';
    setTimeout(() => { this.el.hitVignette.style.opacity = '0'; }, 130);
  }

  whiteFlash(strength = 0.2) {
    this.el.flash.style.transition = 'none';
    this.el.flash.style.opacity = String(strength);
    setTimeout(() => {
      this.el.flash.style.transition = 'opacity .35s ease-out';
      this.el.flash.style.opacity = '0';
    }, 30);
  }

  /* ------------------------------- death ------------------------------- */
  showDeath(loss, seconds, onCount) {
    this.el.death.classList.remove('hidden');
    this.el.deathLoss.textContent = this.formatNumber(loss);
    this.el.deathCount.textContent = seconds;
    this.deathTimer = setInterval(() => {
      seconds -= 1;
      this.el.deathCount.textContent = Math.max(0, seconds);
      onCount?.(seconds);
      if (seconds <= 0) {
        clearInterval(this.deathTimer);
        this.deathTimer = null;
      }
    }, 1000);
  }

  hideDeath() {
    this.el.death.classList.add('hidden');
    if (this.deathTimer) clearInterval(this.deathTimer);
    this.deathTimer = null;
  }

  showVictory() { this.el.victory.classList.remove('hidden'); }
  hideVictory() { this.el.victory.classList.add('hidden'); }
  showPause() { this.el.pause.classList.remove('hidden'); }
  hidePause() { this.el.pause.classList.add('hidden'); }
  showMap() { this.el.map.classList.remove('hidden'); }
  hideMap() { this.el.map.classList.add('hidden'); }
  showHelp() { this.el.help.classList.remove('hidden'); }
  hideHelp() { this.el.help.classList.add('hidden'); }
  get mapOpen() { return !this.el.map.classList.contains('hidden'); }
  get helpOpen() { return !this.el.help.classList.contains('hidden'); }
  get paused() { return !this.el.pause.classList.contains('hidden'); }
  get dead() { return !this.el.death.classList.contains('hidden'); }
  get victorious() { return !this.el.victory.classList.contains('hidden'); }

  /* ------------------------------ compass ------------------------------ */
  updateCompass(yaw) {
    const heading = ((-yaw * 180 / Math.PI) + 360) % 360;
    this.heading = heading;
    for (const { el, angle } of this.compassLabels) {
      let delta = ((angle - heading + 540) % 360) - 180;
      const x = delta * 2.1;
      el.style.left = `calc(50% + ${x.toFixed(1)}px)`;
      el.style.opacity = String(clamp(1 - Math.abs(delta) / 110, 0.08, 1));
      if (Math.abs(delta) < 4) el.style.color = '#ffc857';
      else el.style.color = '';
    }
  }

  /* ------------------------------ minimap ------------------------------ */
  drawMinimap(data) {
    const ctx = this.miniCtx;
    const size = this.el.minimap.width;
    const R = size / 2;
    const scale = size / 620;
    ctx.clearRect(0, 0, size, size);
    ctx.save();
    ctx.beginPath();
    ctx.arc(R, R, R - 3, 0, TAU);
    ctx.clip();
    const g = ctx.createRadialGradient(R, R, 10, R, R, R);
    g.addColorStop(0, '#0d5964');
    g.addColorStop(0.55, '#073741');
    g.addColorStop(1, '#032029');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, size, size);

    const px = data.player.x, pz = data.player.z;
    const toMap = (x, z) => [R + (x - px) * scale, R + (z - pz) * scale];

    // wave rings
    ctx.strokeStyle = 'rgba(100, 220, 215, 0.08)';
    ctx.lineWidth = 2;
    for (let i = 1; i <= 3; i++) {
      ctx.beginPath(); ctx.arc(R, R, i * 52 + (data.time * 6) % 52, 0, TAU); ctx.stroke();
    }

    // islands
    for (const island of data.islands) {
      const [x, y] = toMap(island.x, island.z);
      const r = island.radius * scale;
      if (x + r < 0 || x - r > size || y + r < 0 || y - r > size) continue;
      ctx.beginPath(); ctx.arc(x, y, r * 1.01, 0, TAU);
      ctx.fillStyle = 'rgba(221, 205, 156, .55)'; ctx.fill();
      ctx.beginPath(); ctx.arc(x, y, r * 0.86, 0, TAU);
      ctx.fillStyle = island.biome === 'ember' ? '#5c3b36' : island.biome === 'home' ? '#4e8c4e' : '#5d8256';
      ctx.fill();
      ctx.beginPath(); ctx.arc(x, y, r * 0.25, 0, TAU);
      ctx.fillStyle = island.biome === 'ember' ? 'rgba(255, 88, 24, .55)' : 'rgba(255,255,255,.06)';
      ctx.fill();
      if (island.id === 'dawn') {
        // dock line
        const [dx, dy] = toMap(52, 0);
        ctx.strokeStyle = 'rgba(238,213,165,.7)'; ctx.lineWidth = 3;
        ctx.beginPath(); ctx.moveTo(x + r * 0.55, y); ctx.lineTo(dx, dy); ctx.stroke();
      }
    }

    // enemies
    for (const e of data.enemies) {
      if (!e.alive) continue;
      let [x, y] = toMap(e.x, e.z);
      const dx = x - R, dy = y - R;
      if (Math.hypot(dx, dy) > R - 12) {
        const k = (R - 12) / Math.hypot(dx, dy);
        x = R + dx * k; y = R + dy * k;
      }
      ctx.beginPath(); ctx.arc(x, y, e.boss ? 6 : 3.4, 0, TAU);
      ctx.fillStyle = e.boss ? '#ff4d1a' : '#ff7a5a'; ctx.fill();
      if (e.boss) {
        ctx.beginPath(); ctx.arc(x, y, 11 + Math.sin(data.time * 5) * 1.5, 0, TAU);
        ctx.strokeStyle = 'rgba(255,80,30,.65)'; ctx.lineWidth = 2; ctx.stroke();
      }
    }

    // markers
    const marker = (x, z, color, r = 5, ring = true) => {
      let [mx, my] = toMap(x, z);
      const dx = mx - R, dy = my - R;
      const dist = Math.hypot(dx, dy);
      if (dist > R - 14) { const k = (R - 14) / dist; mx = R + dx * k; my = R + dy * k; }
      if (ring) {
        ctx.beginPath(); ctx.arc(mx, my, r + 4 + Math.sin(data.time * 4) * 1.6, 0, TAU);
        ctx.strokeStyle = color + '66'; ctx.lineWidth = 2; ctx.stroke();
      }
      ctx.beginPath(); ctx.arc(mx, my, r, 0, TAU);
      ctx.fillStyle = color; ctx.fill();
      ctx.strokeStyle = 'rgba(5,20,24,.7)'; ctx.lineWidth = 1.5; ctx.stroke();
    };
    for (const npc of data.npcs || []) marker(npc.x, npc.z, '#ffc857', 5);
    for (const chest of data.chests || []) marker(chest.x, chest.z, '#ffd76a', 4, false);
    if (data.questTarget) marker(data.questTarget.x, data.questTarget.z, '#4cf0d6', 5);

    // boat
    if (data.boat) {
      let [bx, by] = toMap(data.boat.x, data.boat.z);
      const dx = bx - R, dy = by - R, dist = Math.hypot(dx, dy);
      if (dist > R - 12) { const k = (R - 12) / dist; bx = R + dx * k; by = R + dy * k; }
      ctx.save(); ctx.translate(bx, by); ctx.rotate(-data.boat.yaw);
      ctx.fillStyle = '#e7c88b';
      ctx.beginPath(); ctx.moveTo(0, -7); ctx.lineTo(5, 5); ctx.lineTo(0, 2); ctx.lineTo(-5, 5); ctx.closePath(); ctx.fill();
      ctx.restore();
    }

    // player arrow
    ctx.save();
    ctx.translate(R, R);
    ctx.rotate(-data.player.yaw + Math.PI);
    ctx.beginPath();
    ctx.moveTo(0, -14); ctx.lineTo(9, 10); ctx.lineTo(0, 5); ctx.lineTo(-9, 10); ctx.closePath();
    ctx.fillStyle = '#ffe19a';
    ctx.shadowColor = '#ffc857'; ctx.shadowBlur = 12;
    ctx.fill();
    ctx.strokeStyle = 'rgba(55,35,4,.8)'; ctx.lineWidth = 1.5; ctx.stroke();
    ctx.restore();

    // vignette around edge
    ctx.beginPath(); ctx.arc(R, R, R - 2, 0, TAU);
    ctx.strokeStyle = 'rgba(180,240,235,.10)'; ctx.lineWidth = 6; ctx.stroke();
    ctx.restore();
  }

  /* ----------------------------- world map ----------------------------- */
  drawWorldMap(data) {
    const ctx = this.mapCtx;
    const w = this.el.worldMap.width, h = this.el.worldMap.height;
    ctx.clearRect(0, 0, w, h);
    const bounds = { x0: -335, x1: 340, z0: -305, z1: 285 };
    const sx = w / (bounds.x1 - bounds.x0);
    const sz = h / (bounds.z1 - bounds.z0);
    const s = Math.min(sx, sz) * 0.93;
    const ox = w / 2 - ((bounds.x0 + bounds.x1) / 2) * s;
    const oy = h / 2 - ((bounds.z0 + bounds.z1) / 2) * s;
    const toMap = (x, z) => [ox + x * s, oy + z * s];

    // sea
    const bg = ctx.createLinearGradient(0, 0, w, h);
    bg.addColorStop(0, '#082b35');
    bg.addColorStop(0.5, '#06323c');
    bg.addColorStop(1, '#041f28');
    ctx.fillStyle = bg; ctx.fillRect(0, 0, w, h);

    // chart grid
    ctx.strokeStyle = 'rgba(120, 220, 210, 0.055)'; ctx.lineWidth = 1;
    for (let x = -300; x <= 340; x += 50) { const [gx] = toMap(x, 0); ctx.beginPath(); ctx.moveTo(gx, 0); ctx.lineTo(gx, h); ctx.stroke(); }
    for (let z = -300; z <= 280; z += 50) { const [, gy] = toMap(0, z); ctx.beginPath(); ctx.moveTo(0, gy); ctx.lineTo(w, gy); ctx.stroke(); }

    // sea texture dashes
    ctx.strokeStyle = 'rgba(100, 210, 200, 0.07)'; ctx.lineWidth = 2;
    for (let i = 0; i < 26; i++) {
      const x = (i * 211) % w, y = (i * 137) % h;
      ctx.beginPath(); ctx.moveTo(x, y); ctx.quadraticCurveTo(x + 18, y - 6, x + 34, y); ctx.stroke();
    }

    // trade route
    const route = [[0, 0], [225, -58], [-185, 162], [-152, -218]];
    ctx.setLineDash([8, 10]); ctx.strokeStyle = 'rgba(255, 200, 87, 0.18)'; ctx.lineWidth = 2;
    for (let i = 0; i < route.length - 1; i++) {
      const [ax, ay] = toMap(...route[i]); const [bx, by] = toMap(...route[i + 1]);
      ctx.beginPath(); ctx.moveTo(ax, ay); ctx.lineTo(bx, by); ctx.stroke();
    }
    ctx.setLineDash([]);

    // islands
    for (const island of data.islands) {
      const [x, y] = toMap(island.x, island.z);
      const r = island.radius * s;
      // reef glow
      let grd = ctx.createRadialGradient(x, y, r * 0.4, x, y, r * 1.45);
      grd.addColorStop(0, 'rgba(90, 210, 200, .16)'); grd.addColorStop(1, 'rgba(90, 210, 200, 0)');
      ctx.fillStyle = grd; ctx.beginPath(); ctx.arc(x, y, r * 1.45, 0, TAU); ctx.fill();
      // irregular island silhouette
      ctx.beginPath();
      const points = 24;
      for (let i = 0; i <= points; i++) {
        const a = (i / points) * TAU;
        const n = 0.86 + Math.sin(i * 2.7 + island.seed) * 0.09 + Math.sin(i * 5.1) * 0.05;
        const px = x + Math.cos(a) * r * n, py = y + Math.sin(a) * r * n;
        if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
      }
      ctx.closePath();
      ctx.fillStyle = 'rgba(220, 205, 160, .85)'; ctx.fill();
      ctx.save(); ctx.clip();
      const land = ctx.createRadialGradient(x - r * 0.3, y - r * 0.3, r * 0.1, x, y, r);
      if (island.biome === 'ember') { land.addColorStop(0, '#8f4b32'); land.addColorStop(0.5, '#5b3b38'); land.addColorStop(1, '#3e2f30'); }
      else if (island.biome === 'home') { land.addColorStop(0, '#91c56a'); land.addColorStop(0.55, '#4a8c4a'); land.addColorStop(1, '#2e663c'); }
      else { land.addColorStop(0, '#7ca369'); land.addColorStop(0.6, '#4f7c4f'); land.addColorStop(1, '#355d3d'); }
      ctx.fillStyle = land; ctx.fillRect(x - r, y - r, r * 2, r * 2);
      // ridges
      ctx.strokeStyle = 'rgba(20, 40, 30, .18)'; ctx.lineWidth = 2;
      for (let k = -2; k <= 2; k++) {
        ctx.beginPath(); ctx.arc(x + k * r * 0.22, y - r * 0.08, r * 0.32, Math.PI * 1.1, Math.PI * 1.9); ctx.stroke();
      }
      // volcano
      if (island.biome === 'ember') {
        ctx.beginPath(); ctx.arc(x, y, r * 0.16, 0, TAU); ctx.fillStyle = '#ff5a1a'; ctx.fill();
        ctx.beginPath(); ctx.arc(x, y, r * 0.26, 0, TAU); ctx.strokeStyle = 'rgba(255,120,40,.55)'; ctx.lineWidth = 3; ctx.stroke();
      }
      ctx.restore();
      // outline
      ctx.strokeStyle = 'rgba(240, 228, 188, .35)'; ctx.lineWidth = 1.5; ctx.stroke();

      // label
      ctx.textAlign = 'center';
      ctx.font = '700 15px Outfit, sans-serif';
      ctx.fillStyle = 'rgba(255, 246, 218, .92)';
      ctx.shadowColor = 'rgba(0,0,0,.8)'; ctx.shadowBlur = 8;
      ctx.fillText(island.name.toUpperCase(), x, y + r + 21);
      ctx.font = '700 8px Outfit, sans-serif';
      ctx.fillStyle = island.biome === 'ember' ? 'rgba(255,130,90,.8)' : 'rgba(200, 238, 230, .52)';
      ctx.fillText(island.subtitle.toUpperCase(), x, y + r + 34);
      ctx.shadowBlur = 0;

      // dock
      if (island.id === 'dawn') {
        const [dx, dy] = toMap(52, 0);
        ctx.strokeStyle = 'rgba(255, 215, 150, .8)'; ctx.lineWidth = 3;
        ctx.beginPath(); ctx.moveTo(x + r * 0.6, y); ctx.lineTo(dx, dy); ctx.stroke();
      }
      if (island.id === 'ember') {
        const [bx, by] = toMap(238, -38);
        ctx.beginPath(); ctx.arc(bx, by, 6 + Math.sin(data.time * 4) * 1.5, 0, TAU);
        ctx.fillStyle = '#ff4d1a'; ctx.fill();
        ctx.beginPath(); ctx.arc(bx, by, 13, 0, TAU);
        ctx.strokeStyle = 'rgba(255,77,26,.5)'; ctx.lineWidth = 2; ctx.stroke();
      }
    }

    // quest target
    if (data.questTarget) {
      const [x, y] = toMap(data.questTarget.x, data.questTarget.z);
      ctx.strokeStyle = '#4cf0d6'; ctx.lineWidth = 2;
      ctx.beginPath(); ctx.arc(x, y, 15 + Math.sin(data.time * 4) * 2, 0, TAU); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(x - 5, y); ctx.lineTo(x + 5, y); ctx.moveTo(x, y - 5); ctx.lineTo(x, y + 5); ctx.stroke();
    }

    // boat
    if (data.boat) {
      const [x, y] = toMap(data.boat.x, data.boat.z);
      ctx.save(); ctx.translate(x, y); ctx.rotate(-data.boat.yaw);
      ctx.fillStyle = '#f0d49a';
      ctx.beginPath(); ctx.moveTo(0, -10); ctx.lineTo(7, 7); ctx.lineTo(0, 3); ctx.lineTo(-7, 7); ctx.closePath(); ctx.fill();
      ctx.restore();
    }

    // player
    const [px, py] = toMap(data.player.x, data.player.z);
    ctx.save(); ctx.translate(px, py); ctx.rotate(-data.player.yaw + Math.PI);
    ctx.beginPath(); ctx.moveTo(0, -16); ctx.lineTo(10, 11); ctx.lineTo(0, 5); ctx.lineTo(-10, 11); ctx.closePath();
    ctx.fillStyle = '#ffe19a'; ctx.shadowColor = '#ffc857'; ctx.shadowBlur = 16; ctx.fill();
    ctx.strokeStyle = 'rgba(50,30,4,.9)'; ctx.lineWidth = 2; ctx.stroke();
    ctx.restore();

    // compass rose
    const cx = w - 78, cy = h - 70;
    ctx.save(); ctx.translate(cx, cy);
    ctx.strokeStyle = 'rgba(255,200,87,.22)'; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.arc(0, 0, 38, 0, TAU); ctx.stroke();
    ctx.beginPath(); ctx.arc(0, 0, 28, 0, TAU); ctx.stroke();
    ctx.fillStyle = 'rgba(255,200,87,.7)'; ctx.font = '700 9px Outfit'; ctx.textAlign = 'center';
    ctx.fillText('N', 0, -45); ctx.fillText('S', 0, 50); ctx.fillText('E', 47, 3); ctx.fillText('W', -47, 3);
    ctx.beginPath(); ctx.moveTo(0, -24); ctx.lineTo(5, 0); ctx.lineTo(0, 24); ctx.lineTo(-5, 0); ctx.closePath();
    ctx.fillStyle = 'rgba(255,200,87,.4)'; ctx.fill();
    ctx.restore();

    // border and title
    ctx.strokeStyle = 'rgba(255, 200, 87, .12)'; ctx.strokeRect(0.5, 0.5, w - 1, h - 1);
    ctx.fillStyle = 'rgba(255,200,87,.4)'; ctx.font = '700 9px Outfit'; ctx.textAlign = 'left';
    ctx.fillText('THE GRAND TIDE · NAVIGATION CHART · SCALE 1:12', 16, 22);
    if (data.mapCoords) this.el.mapCoords.textContent = data.mapCoords;
  }

  /* ------------------------------ touch -------------------------------- */
  initTouch() {
    const joy = $('joystick');
    const knob = $('joy-knob');
    let joyId = null;
    const max = 46;
    const update = (e) => {
      const rect = joy.getBoundingClientRect();
      const cx = rect.left + rect.width / 2;
      const cy = rect.top + rect.height / 2;
      let dx = e.clientX - cx, dy = e.clientY - cy;
      const d = Math.hypot(dx, dy);
      if (d > max) { dx = dx / d * max; dy = dy / d * max; }
      knob.style.transform = `translate(${dx}px, ${dy}px)`;
      this.touchMove.x = dx / max;
      this.touchMove.y = -dy / max;
    };
    joy.addEventListener('pointerdown', e => {
      joyId = e.pointerId; joy.setPointerCapture(e.pointerId); update(e); e.preventDefault();
    });
    joy.addEventListener('pointermove', e => { if (e.pointerId === joyId) update(e); });
    const end = e => {
      if (e.pointerId !== joyId) return;
      joyId = null; this.touchMove.x = 0; this.touchMove.y = 0;
      knob.style.transform = '';
    };
    joy.addEventListener('pointerup', end);
    joy.addEventListener('pointercancel', end);

    document.querySelectorAll('#touch-actions .touch-btn').forEach(btn => {
      btn.addEventListener('pointerdown', e => {
        e.preventDefault();
        this.touchQueue.push(btn.dataset.action);
        btn.classList.add('pressed');
      });
      btn.addEventListener('pointerup', () => btn.classList.remove('pressed'));
      btn.addEventListener('pointercancel', () => btn.classList.remove('pressed'));
    });
  }

  consumeTouch() { return this.touchQueue.splice(0); }

  formatNumber(n) {
    const v = Math.round(n);
    if (v >= 1_000_000) return `${(v / 1_000_000).toFixed(2)}M`;
    if (v >= 10_000) return `${(v / 1000).toFixed(1)}K`;
    return v.toLocaleString('en-US');
  }
}

export { FRUIT_DATA };

