+function boardBoat() {
+  if (player.onBoat) return;
+  const d = Math.hypot(player.pos.x - boatState.pos.x, player.pos.z - boatState.pos.z);
+  if (d > 6.5) { ui.toast('Get closer to the skiff', { icon: '⚓', time: 1600 }); return; }
+  player.onBoat = true;
