+  look.pitch = 0.26;
+  look.yaw = boatState.yaw + Math.PI;
+  ui.toast('<b>Skiff boarded</b> · W/S sail · A/D steer · F to disembark', { icon: '⚓', kind: 'gold', time: 5200 });
+  audio.board();
