  const THREE = await import('/vendor/three.module.min.js');
  const { scene, camera } = window.__fb;
  const rc = new THREE.Raycaster();
  const out = [];
  const coords = [[0.53,-0.04],[0.7,-0.12],[0.35,-0.15],[0.75,0.1]];
  for (const [nx, ny] of coords) {
    rc.setFromCamera(new THREE.Vector2(nx, ny), camera);
    const hits = rc.intersectObjects(scene.children, true).slice(0, 6);
    out.push({
      nx, ny,
      hits: hits.map(h => ({
        d: +h.distance.toFixed(1),
        p: h.point.toArray().map(v => +v.toFixed(1)),
        m: h.object.material.type,
        c: h.object.material.color && h.object.material.color.getHexString(),
        vc: h.object.material.vertexColors ? 'v' : ''
      }))
    });
  }
  return JSON.stringify(out);
}
